UPDATE banks SET questions_json = '[{"id":1,"type":"single","category":"精密切削","difficulty":2,"question":"下列金刚石(        )晶面的面密度最大，硬度和耐磨性最高。","options":["A. (110)","B. (111)","C. (101)","D. (100)"],"answer":"B","explanation":"金刚石(111)晶面的面网密度最大，硬度和耐磨性最高。其他晶面如(110)、(101)、(100)的密度和硬度都较低。记忆口诀：\\"111最密最硬\\"。"},{"id":2,"type":"single","category":"精密切削","difficulty":2,"question":"加工机械的不均匀温升会导致加工精度哪些误差(        )。","options":["A. 形状精度","B. 以上都有","C. 尺寸精度","D. 位置精度"],"answer":"B","explanation":"不均匀温升会导致机床各部件热变形不一致，从而同时影响形状精度、尺寸精度和位置精度。三者都会受影响，所以选以上都有。记忆：热变形\\"三精度全影响\\"。"},{"id":3,"type":"single","category":"精密切削","difficulty":3,"question":"以下关于超精密切削的特殊性，正确的是(        )。","options":["A. 积屑瘤将使金刚石刀具的刃口半径显著增加,实际切削厚度增大，工件、切屑与刀具的摩擦加剧，从而导致切削力明显增大，加工表面质量严重恶化。","B. 金刚石刀具切削力随切削速度的增加而减小，切削厚度越小，切削应力越大。","C. 以上都是","D. 切削速度对金刚石刀具的磨损影响甚微。"],"answer":"C","explanation":"超精密切削的特殊性包括：积屑瘤会恶化表面质量；切削力随速度增加而减小；切削厚度越小应力越大；切削速度对金刚石磨损影响小。以上描述均正确。记忆：超精密\\"四特殊\\"。"},{"id":4,"type":"single","category":"精密切削","difficulty":2,"question":"金刚石磨料不是加工(        )。","options":["A. 硬质合金","B. 玻璃","C. 陶瓷","D. 钢铁"],"answer":"D","explanation":"金刚石中的碳元素会与钢铁中的铁发生化学反应（石墨化），导致金刚石快速磨损。因此金刚石不适合加工钢铁材料，但可加工硬质合金、玻璃、陶瓷。记忆：金刚石\\"怕铁不怕硬\\"。"},{"id":5,"type":"single","category":"精密切削","difficulty":3,"question":"精密切削的最小切削厚度hDmin(        )。","options":["A. 与刀具和工件材料之间的摩擦系数μ有关。","B. 与材料微观缺陷、微观弹性变形和塑性变形量有关。","C. 以上都是。","D. 与刀具的刃口圆弧半径ρ相关"],"answer":"C","explanation":"最小切削厚度受多种因素影响：摩擦系数μ、材料微观特性、刃口圆弧半径ρ等，是一个综合性的参数。以上因素都有影响。记忆：hDmin\\"三因素\\"。"},{"id":6,"type":"single","category":"精密磨削","difficulty":2,"question":"砂轮硬度跟以下(        )无关。","options":["A. 制造工艺","B. 以上都不是。","C. 磨粒硬度","D. 结合剂强度"],"answer":"C","explanation":"砂轮硬度是指磨粒从砂轮表面脱落的难易程度，取决于结合剂的强度和制造工艺，与磨粒本身的硬度无关。记忆：砂轮硬度看\\"结合剂\\"，不看\\"磨粒\\"。"},{"id":7,"type":"single","category":"精密磨削","difficulty":2,"question":"超精密加工机床中导轨采用的是(        )。","options":["A. 气浮导轨","B. 滚动导轨","C. 液体静压导轨","D. 滑动导轨"],"answer":"C","explanation":"超精密加工机床要求极高的运动精度和稳定性，液体静压导轨摩擦小、运动平稳、精度高，是首选方案。气浮导轨和滚动导轨精度稍低。记忆：超精密用\\"液体静压\\"。"},{"id":8,"type":"single","category":"精密磨削","difficulty":2,"question":"下面(        )不是特种加工具有的特点。","options":["A. 工具硬度可以低于被加工材料的硬度","B. 一些加工方法可以复合使用，形成一种新工艺","C. 加工过程中，工具和工件之间不存在显著的切削力","D. 主要依靠机械能去除材料"],"answer":"D","explanation":"特种加工主要依靠电能、热能、化学能、光能等非机械能去除材料，而不是传统的机械切削。工具硬度可以低于工件、可复合使用、无显著切削力都是特点。记忆：特种加工\\"非机械能\\"。"},{"id":9,"type":"single","category":"精密磨削","difficulty":2,"question":"(        )不是精密加工机床的基本要求。","options":["A. 无需自动化","B. 高稳定性","C. 高刚度","D. 高精度"],"answer":"A","explanation":"精密加工机床需要高精度、高刚度、高稳定性，同时需要自动化来保证加工的一致性和减少人为误差。无需自动化是错误的。记忆：精密机床\\"三高一自动\\"。"},{"id":10,"type":"single","category":"精密磨削","difficulty":2,"question":"砂轮磨削一段时间之后，它的(        )会得到改善和提高。","options":["A. 磨粒的微刃性","B. 磨粒的等高性","C. 微刃的滑擦、挤压、抛光作用","D. B和C"],"answer":"D","explanation":"砂轮经过一段时间磨削后，磨粒的等高性改善，微刃的滑擦、挤压、抛光作用增强，这被称为砂轮的\\"自锐\\"过程。微刃性不会自动改善。记忆：砂轮自锐\\"等高+滑擦\\"。"},{"id":11,"type":"single","category":"精密磨削","difficulty":2,"question":"对于精密磨削和超精密磨削磨具，描述不正确的是(        )。","options":["A. 磨粒从磨具表面容易脱落，则其硬度低","B. 对各类磨具(砂轮)没有最高工作线速度的规定","C. 普通磨料是指刚玉系和碳化物系磨料","D. 超硬磨具的硬度一般较高"],"answer":"B","explanation":"各类砂轮都有最高工作线速度的限制，超过规定速度会导致砂轮破裂，造成安全事故。其他描述正确。记忆：砂轮\\"限速保安全\\"。"},{"id":12,"type":"single","category":"精密切削","difficulty":2,"question":"下列对立方晶系的天然金刚石描述不正确的是，天然金刚石有(        )。","options":["A. 8面体","B. 6面体","C. 4面体","D. 12面体"],"answer":"C","explanation":"天然金刚石属于立方晶系，常见的晶形有6面体（立方体）、8面体和12面体（菱形十二面体），没有4面体。记忆：金刚石\\"6、8、12\\"面体。"},{"id":13,"type":"single","category":"精密磨削","difficulty":3,"question":"树脂结合剂砂轮比陶瓷结合剂砂轮有以下(        )的优势。","options":["A. 弹性模量小，磨削质量稳定, 不容易产生螺旋形/烧伤等缺陷","B. 更能获得更细的工件表面粗糙度。","C. 热膨胀量小，磨削精度高。","D. 耐热性能好，切削锋利，磨削效率高，砂轮不易发热和堵塞。"],"answer":"A","explanation":"树脂结合剂弹性好，能吸收振动，磨削时不易产生烧伤和螺旋形缺陷，表面质量稳定。陶瓷结合剂硬度高但脆性大。记忆：树脂\\"弹性好防烧伤\\"。"},{"id":14,"type":"single","category":"精密磨削","difficulty":2,"question":"精密磨削使用的刚玉系砂轮不具有的特点(        )。","options":["A. 磨料韧性较高","B. 微刃等高性保持好","C. 微刃性保持好","D. 磨料韧性差、磨削铸铁"],"answer":"D","explanation":"刚玉系砂轮韧性较高，微刃性和等高性保持好，适合精密磨削。刚玉韧性好不是差。记忆：刚玉\\"韧性好\\"。"},{"id":15,"type":"single","category":"精密切削","difficulty":2,"question":"下列(        )不能用金刚石刀具进行切削加工。","options":["A. 陶瓷","B. SiO2","C. 工具钢","D. 玻璃"],"answer":"C","explanation":"金刚石刀具不能加工钢铁材料，因为碳元素会与铁发生化学反应，导致刀具快速磨损。陶瓷、SiO2、玻璃都可以加工。记忆：金刚石\\"怕铁\\"。"},{"id":16,"type":"single","category":"精密磨削","difficulty":3,"question":"高精度、低表面粗糙度值的精密和超精密磨削选用(        )。","options":["A. 高质量浓度砂轮","B. 细粒度、中等质量浓度砂轮","C. 细粒度、低质量浓度砂轮","D. 都可以"],"answer":"C","explanation":"精密磨削要求低粗糙度，应选用细粒度砂轮（切削刃多）和低质量浓度（磨粒少，切削力小）。高质量浓度适合粗加工。记忆：精密磨削\\"细粒低浓\\"。"},{"id":17,"type":"single","category":"精密切削","difficulty":2,"question":"对天然金刚石晶体叙述不正确的是(        )。","options":["A. 金刚石有好磨方向","B. 解理现象","C. 金刚石硬度最高","D. 各向同性"],"answer":"D","explanation":"金刚石是各向异性材料，不同晶面和晶向的硬度、耐磨性差异很大，不是各向同性。记忆：金刚石\\"各向异性\\"。"},{"id":18,"type":"single","category":"精密磨削","difficulty":2,"question":"超精密加工机床中主轴的驱动方式是(        )","options":["A. 电动机通过柔性联轴节驱动","B. B与C两种方式都有","C. 电动机通过带传动驱动","D. 内装式同轴电动机驱动"],"answer":"B","explanation":"超精密机床主轴驱动方式包括柔性联轴节驱动和内装式同轴电动机驱动两种，根据精度要求选择。两种方式都有应用。记忆：主轴驱动\\"两种方式\\"。"},{"id":19,"type":"single","category":"精密切削","difficulty":2,"question":"以下(        )不是金刚石刀具的磨损形式。","options":["A. 碳化磨损。","B. 相变磨损","C. 机械磨损","D. 破损"],"answer":"B","explanation":"金刚石刀具的磨损形式包括机械磨损、碳化磨损（与铁反应）、破损等，相变磨损不是金刚石的磨损形式。记忆：金刚石磨损\\"三形式\\"。"},{"id":20,"type":"single","category":"精密磨削","difficulty":2,"question":"铸铁零件的精密和超精密磨削应选用(        )。","options":["A. 陶瓷砂轮","B. 金刚石砂轮","C. 碳化物系砂轮","D. 刚玉(氧化物)系砂轮"],"answer":"C","explanation":"铸铁属于脆性材料，碳化物系砂轮（如碳化硅）硬度高、脆性大，适合磨削铸铁。刚玉系砂轮适合磨钢。记忆：铸铁用\\"碳化物\\"砂轮。"},{"id":21,"type":"single","category":"精密切削","difficulty":3,"question":"以下(        )不是立方氮化硼刀具比天然金刚石刀具的优势。","options":["A. 硬度更高，耐磨性能更好。","B. 各向同性，刀具加工是不需要挑选特殊的方向，省时省力。","C. 化学惰性大，与铁原子的亲合力小，不与钢铁材料发生粘着现象。","D. 热稳定性好，工作温度更高。"],"answer":"A","explanation":"立方氮化硼硬度略低于金刚石，但其优势是各向同性、化学惰性大（可加工钢铁）、热稳定性好。硬度更高是错误的。记忆：CBN\\"硬度稍低但全能\\"。"},{"id":22,"type":"single","category":"精密磨削","difficulty":3,"question":"以下磨粒脱落的可能原因，(        )不正确。","options":["A. 砂轮强度过低","B. 切削深度过大，切削力增大","C. 切削刃变钝，切削力增大","D. 砂轮硬度过软"],"answer":"A","explanation":"磨粒脱落主要与砂轮硬度、切削力有关。砂轮硬度过软、切削深度过大、切削刃变钝都会导致磨粒脱落，而砂轮强度过低主要影响砂轮破裂。记忆：磨粒脱落看\\"硬度和切削力\\"。"},{"id":23,"type":"single","category":"精密磨削","difficulty":2,"question":"以下(        )不是抛光比研磨的优势。","options":["A. 加工精度更高","B. 加工效率更高","C. 粗糙度Ra值更小","D. 以上都不是"],"answer":"A","explanation":"抛光主要改善表面粗糙度，但不能提高尺寸精度和形状精度，而研磨可以提高精度。抛光精度更高是错误的。记忆：抛光\\"只改善粗糙度\\"。"},{"id":24,"type":"single","category":"精密磨削","difficulty":2,"question":"超精密加工机床中主轴部件的轴承采用的是(        )。","options":["A. 滑动轴承","B. 磁悬浮轴承","C. 滚动轴承","D. 液体静压轴承"],"answer":"D","explanation":"液体静压轴承精度高、刚度好、运动平稳，是超精密机床主轴的首选轴承类型。滚动轴承精度稍低。记忆：超精密主轴用\\"液体静压\\"。"},{"id":25,"type":"single","category":"精密磨削","difficulty":3,"question":"以下(        )不是产生砂轮轮廓畸变的原因。","options":["A. 磨削时间长","B. 砂轮的浓度低，组织疏松","C. 砂轮硬度过软","D. 砂轮强度过低"],"answer":"D","explanation":"砂轮轮廓畸变与磨削时间、砂轮浓度、硬度有关，砂轮强度过低主要导致砂轮破裂而非轮廓畸变。记忆：轮廓畸变\\"三因素\\"。"},{"id":26,"type":"single","category":"精密磨削","difficulty":2,"question":"以下(        )影响砂轮的动平衡效果。","options":["A. 砂轮粒度","B. 砂轮硬度","C. 磨料硬度","D. 砂轮强度"],"answer":"D","explanation":"砂轮强度影响动平衡效果，强度不足会导致砂轮在高速旋转时变形或破裂，影响平衡。粒度、硬度、磨料硬度影响较小。记忆：动平衡看\\"强度\\"。"},{"id":27,"type":"single","category":"精密磨削","difficulty":2,"question":"砂轮的动平衡测试的目的是(        )。","options":["A. 安全","B. 磨削质量","C. 磨床精度保持","D. 以上都是。"],"answer":"D","explanation":"动平衡测试同时保证安全（防止砂轮破裂）、磨削质量（减少振动）和磨床精度保持（减少磨损）。三者都是目的。记忆：动平衡\\"三保证\\"。"},{"id":28,"type":"single","category":"精密切削","difficulty":2,"question":"一般不选择金刚石的(        )晶面作为切削的加工面。","options":["A. (100)","B. (110)","C. (101)","D. (111)"],"answer":"D","explanation":"(111)晶面硬度最高、耐磨性最好，但不易加工，一般选择(100)或(110)晶面作为切削面。记忆：切削面\\"避开111\\"。"},{"id":29,"type":"single","category":"精密磨削","difficulty":2,"question":"砂轮修整之后主要利用它的(        )起磨削工作的。","options":["A. 以上都不是。","B. 磨粒的微刃性","C. 磨粒的等高性","D. 微刃的滑擦、挤压、抛光作用"],"answer":"B","explanation":"砂轮修整后产生新的微刃，主要利用磨粒的微刃性进行切削工作。等高性和滑擦抛光作用是后续改善的。记忆：修整后用\\"微刃性\\"。"},{"id":30,"type":"single","category":"精密切削","difficulty":1,"question":"现代制造技术要求提高零件的加工精度，是为了(        )。","options":["A. 提高产品的性能和质量","B. 保证产品的稳定性和可靠性","C. 促进产品的小型化和零件的互换性","D. 以上三种都是"],"answer":"D","explanation":"提高加工精度可以同时提高产品性能、保证稳定可靠、促进小型化和互换性。三者都是目的。记忆：精度提高\\"三好处\\"。"},{"id":31,"type":"single","category":"精密切削","difficulty":2,"question":"目前(        )微量进给装置应用的最成熟和普遍。","options":["A. 磁致伸缩式","B. 热变形式:","C. 机械或液压传动式","D. 弹性变形式和电致伸缩式"],"answer":"D","explanation":"弹性变形式和电致伸缩式微量进给装置精度高、响应快，应用最成熟和普遍。磁致伸缩式和热变形式也有应用但不如前者广泛。记忆：微量进给\\"弹性+电致伸缩\\"。"},{"id":32,"type":"single","category":"精密切削","difficulty":3,"question":"金刚石晶体的各向异性表现为(        )","options":["A. 金刚石晶体各个晶面的面网密度不一样，110晶面的面网密度最小","B. 金刚石晶体各个晶面的耐磨性不一样，同一晶面不同方向上的耐磨性不一样","C. 金刚石晶体各个晶面的硬度不一样，110晶面的硬度最高","D. 金刚石晶体各个晶面的耐磨性不一样，110晶面的磨削率最低，最不易磨削"],"answer":"B","explanation":"金刚石各向异性表现为不同晶面耐磨性不同，同一晶面不同方向耐磨性也不同。面网密度和硬度也有差异但耐磨性最典型。记忆：各向异性\\"耐磨性不同\\"。"},{"id":33,"type":"single","category":"精密磨削","difficulty":3,"question":"超精密加工机床中导轨采用的是(        )。","options":["A. 人造花岗岩","B. 合金铸铁","C. 球墨铸铁","D. 花岗岩"],"answer":"A","explanation":"超精密机床床身常采用人造花岗岩，具有热稳定性好、振动衰减能力强等优点。天然花岗岩也有使用但人造更好。记忆：床身用\\"人造花岗岩\\"。"},{"id":34,"type":"single","category":"精密切削","difficulty":2,"question":"适合切削加工淬火钢和冷硬铸铁的刀具是(        )。","options":["A. CVD金刚石刀具","B. 聚晶金刚石PCD","C. 聚晶立方氮化硼PCBN","D. 单晶金刚石"],"answer":"C","explanation":"PCBN硬度高、化学惰性大，特别适合加工淬火钢、冷硬铸铁等黑色金属硬材料。金刚石不能加工钢铁。记忆：PCBN\\"专切黑色金属\\"。"},{"id":35,"type":"single","category":"精密磨削","difficulty":2,"question":"对于精密磨削和超精密磨削磨具，描述不正确的是(        )。","options":["A. 结合剂对修正方法有影响","B. 结合剂对化学稳定性有影响","C. 结合剂对砂轮自锐性没有影响","D. 结合剂对砂轮的结合强度有影响"],"answer":"C","explanation":"结合剂直接影响砂轮的自锐性，不同结合剂的自锐性能差异很大。说没有影响是错误的。记忆：结合剂影响\\"自锐性\\"。"},{"id":36,"type":"single","category":"精密切削","difficulty":2,"question":"不属于天然单晶金刚石刀具特点的是(        )。","options":["A. 硬度极高、耐磨性好","B. 强度高、导热性好","C. 能切削加工黑色金属","D. 能磨出极锋锐的切削刃"],"answer":"C","explanation":"天然单晶金刚石不能加工黑色金属（钢铁），因为会发生化学反应导致刀具磨损。硬度高、导热好、能磨出锋利刃都是特点。记忆：金刚石\\"不能切钢铁\\"。"},{"id":37,"type":"single","category":"精密切削","difficulty":2,"question":"下面(        )不是精密切削加包括的内容。","options":["A. 稳定工作环境","B. 机床和工艺装备","C. 测量和误差补偿技术","D. 普通刀具材料及切削机理"],"answer":"D","explanation":"精密切削需要特殊刀具材料（如金刚石）和精密切削机理，不是普通刀具材料。其他都是精密切削的内容。记忆：精密切削用\\"特殊刀具\\"。"},{"id":38,"type":"single","category":"精密磨削","difficulty":2,"question":"以下(        )不是砂带磨削比砂轮磨削的优势。","options":["A. 表面质量更好","B. 磨削温度更低","C. 磨削精度更高","D. 磨削效率更高"],"answer":"C","explanation":"砂带磨削效率高、温度低、表面质量好，但精度不如砂轮磨削高。说精度更高是错误的。记忆：砂带\\"效率高精度低\\"。"},{"id":39,"type":"single","category":"精密磨削","difficulty":3,"question":"磨削的粗糙度Ra降低，没有借助砂轮的(        )作用。","options":["A. 微刃的滑擦、挤压、抛光作用","B. 磨粒的等高性","C. 磨粒的微刃性","D. 以上都不是。"],"answer":"C","explanation":"降低粗糙度主要借助微刃的滑擦、挤压、抛光作用和磨粒的等高性，而不是微刃性。微刃性是切削作用。记忆：粗糙度靠\\"滑擦抛光\\"。"},{"id":40,"type":"single","category":"精密磨削","difficulty":1,"question":"精密与特种加工方法包括(        )。","options":["A. 特种加工","B. 传统加工","C. 复合加工","D. 以上三种都是"],"answer":"D","explanation":"精密与特种加工包括传统精密加工、特种加工和复合加工三大类。三者都属于。记忆：精密加工\\"三大类\\"。"},{"id":41,"type":"single","category":"精密切削","difficulty":2,"question":"精密切削过程中，切削液有(        )作用。","options":["A. 减少切削力，降低切削温度，提高切削精度。","B. 减小刀具磨损，提高刀具耐用度","C. 以上都是","D. 抑制积屑瘤的生成"],"answer":"C","explanation":"切削液在精密切削中具有冷却、润滑、清洗等多重作用，可减少切削力、降低温度、抑制积屑瘤、提高精度和刀具寿命。以上都是其作用。记忆：切削液\\"四作用\\"。"},{"id":42,"type":"single","category":"精密磨削","difficulty":1,"question":"下列不属于磨削液基本性能的是(        )。","options":["A. 清洗性能","B. 经济性能","C. 润滑性能","D. 冷却性能"],"answer":"B","explanation":"磨削液的基本性能包括冷却性能、润滑性能、清洗性能和防锈性能，经济性能不属于基本性能。记忆：磨削液\\"四性能\\"。"},{"id":43,"type":"single","category":"精密切削","difficulty":2,"question":"聚晶立方氮化硼(PCBN)刀具最适合加工的材料是(        )。","options":["A. 淬硬钢、冷硬铸铁等黑色金属","B. 高硬度的有色金属(如铜合金)","C. 塑料、陶瓷等非金属材料","D. 钛合金、高温合金"],"answer":"A","explanation":"PCBN化学惰性大，不与钢铁反应，特别适合加工淬硬钢、冷硬铸铁等黑色金属。记忆：PCBN\\"切黑色金属\\"。"},{"id":44,"type":"single","category":"精密磨削","difficulty":2,"question":"精密和超精密磨削加工砂轮粒度的选择与哪项无关(        )。","options":["A. 硬度","B. 磨料","C. 加工材料","D. 加工要求"],"answer":"A","explanation":"砂轮粒度选择与加工要求、加工材料、磨料种类有关，与砂轮硬度无关。硬度影响的是磨粒脱落。记忆：粒度选择\\"三因素\\"。"},{"id":45,"type":"single","category":"精密切削","difficulty":2,"question":"天然金刚石没有哪个晶面(        )。","options":["A. (100)晶面","B. (110)晶面","C. (001)晶面","D. (111)晶面"],"answer":"C","explanation":"天然金刚石属于立方晶系，有(100)、(110)、(111)三种晶面，没有(001)晶面。记忆：金刚石\\"三种晶面\\"。"},{"id":46,"type":"judge","category":"精密切削","difficulty":2,"question":"金刚石的破损和磨损与(111)晶面的解理现象有关。","options":[],"answer":true,"explanation":"正确。金刚石(111)晶面是解理面，容易沿此面解理破裂，与金刚石的破损和磨损密切相关。记忆：111面是\\"解理面\\"。"},{"id":47,"type":"judge","category":"精密磨削","difficulty":2,"question":"超精密机床的导轨部件都是铸铁制造的。","options":[],"answer":false,"explanation":"错误。超精密机床导轨常采用人造花岗岩、液体静压导轨等，不是都用铸铁制造。记忆：超精密导轨\\"非铸铁\\"。"},{"id":48,"type":"judge","category":"精密切削","difficulty":2,"question":"金刚石(111)晶面的硬度和耐磨性最高，实际生产过程要磨削加工此面，拟提高金刚石刀具使用寿命。","options":[],"answer":false,"explanation":"错误。虽然(111)晶面硬度最高，但该面也是解理面，不易加工，实际生产中通常选择(100)或(110)晶面。记忆：切削面\\"避开111\\"。"},{"id":49,"type":"judge","category":"精密磨削","difficulty":1,"question":"砂带磨削分为开式砂带磨削和闭式砂带磨削两大类。","options":[],"answer":true,"explanation":"正确。砂带磨削按砂带运动方式分为开式（单向运动）和闭式（循环运动）两大类。记忆：砂带\\"开式和闭式\\"。"},{"id":50,"type":"judge","category":"精密磨削","difficulty":2,"question":"金属材料的研磨，其特点之一是没有裂纹。","options":[],"answer":true,"explanation":"正确。金属材料具有塑性，研磨时不会像脆性材料那样产生裂纹。记忆：金属研磨\\"无裂纹\\"。"},{"id":51,"type":"judge","category":"精密磨削","difficulty":1,"question":"超硬磨料主要指金刚石和立方氮化硼两类磨料。","options":[],"answer":true,"explanation":"正确。超硬磨料是指硬度特别高的磨料，主要包括金刚石和立方氮化硼(CBN)两类。记忆：超硬磨料\\"两种\\"。"},{"id":52,"type":"judge","category":"精密磨削","difficulty":2,"question":"采用高精度的滚动轴承主轴机床，可加工出任何加工精度要求和表面粗糙度要求的工件。","options":[],"answer":false,"explanation":"错误。滚动轴承有精度极限，超高精度加工需要采用液体静压轴承或气浮轴承。记忆：超高精度\\"不用滚动轴承\\"。"},{"id":53,"type":"judge","category":"精密磨削","difficulty":2,"question":"金属材料的研磨和脆性材料的研磨在加工机理上没有区别。","options":[],"answer":false,"explanation":"错误。金属材料研磨主要靠塑性变形去除，脆性材料靠脆性断裂去除，机理不同。记忆：金属和脆性材料\\"机理不同\\"。"},{"id":54,"type":"judge","category":"精密磨削","difficulty":2,"question":"用细粒度、密组织或硬度大的砂轮磨削软钢或有色金属等材料，易出现堵塞问题。","options":[],"answer":true,"explanation":"正确。软钢和有色金属切屑易粘附，细粒度、密组织砂轮容屑空间小，容易堵塞。记忆：软材料\\"易堵塞\\"。"},{"id":55,"type":"judge","category":"精密磨削","difficulty":2,"question":"特种加工的精度、表面质量、生产率及经济性均优于传统切削加工。","options":[],"answer":false,"explanation":"错误。特种加工在某些方面有优势，但不是所有方面都优于传统加工，各有适用范围。记忆：特种加工\\"有局限\\"。"},{"id":56,"type":"judge","category":"精密磨削","difficulty":2,"question":"在超精密磨削时，如工件为硬质合金，需选用超硬磨料砂轮。","options":[],"answer":true,"explanation":"正确。硬质合金硬度很高，普通磨料难以加工，必须使用金刚石或CBN等超硬磨料砂轮。记忆：硬质合金用\\"超硬磨料\\"。"},{"id":57,"type":"judge","category":"精密切削","difficulty":2,"question":"超精密切削加工的机理和普通切削加工的机理没有区别。","options":[],"answer":false,"explanation":"错误。超精密切削切削厚度极小，接近材料晶格尺寸，加工机理与普通切削有本质区别。记忆：超精密\\"机理不同\\"。"},{"id":58,"type":"judge","category":"精密磨削","difficulty":2,"question":"抛光既不能提高工件尺寸精度，也不能提高形状精度。","options":[],"answer":true,"explanation":"正确。抛光主要改善表面粗糙度，不能修正尺寸误差和形状误差。记忆：抛光\\"只改善粗糙度\\"。"},{"id":59,"type":"judge","category":"精密切削","difficulty":2,"question":"切削厚度越小，切削应力越小。","options":[],"answer":false,"explanation":"错误。在超精密切削中，切削厚度越小，切削应力反而越大（尺寸效应）。记忆：超精密\\"尺寸效应\\"。"},{"id":60,"type":"judge","category":"精密磨削","difficulty":2,"question":"抛光一般不能提高工件形状精度和尺寸精度。","options":[],"answer":true,"explanation":"正确。抛光是光整加工，主要改善表面质量，不能提高形状精度和尺寸精度。记忆：抛光\\"不提高精度\\"。"},{"id":61,"type":"judge","category":"精密磨削","difficulty":2,"question":"粒度号越大，磨削加工表面粗糙度值越大，表面越粗糙。","options":[],"answer":false,"explanation":"错误。粒度号越大，磨粒越细，加工表面粗糙度值越小，表面越光滑。记忆：粒度号\\"越大越细\\"。"},{"id":62,"type":"judge","category":"精密磨削","difficulty":2,"question":"精密磨削加工硬质合金、陶瓷、玻璃、半导体材料及石材等难加工材料时，目前主要使用金刚石砂轮和立方氮化硼(CBN)砂轮。","options":[],"answer":true,"explanation":"正确。这些难加工材料硬度高，必须使用超硬磨料（金刚石或CBN）砂轮才能有效加工。记忆：难加工材料用\\"超硬磨料\\"。"},{"id":63,"type":"judge","category":"精密切削","difficulty":2,"question":"积屑瘤对于普通切削加工来说，可以保护切削刃，降低切削力，但对于超精密加工来说，没有一点好处。","options":[],"answer":true,"explanation":"正确。超精密切削要求极高精度，积屑瘤会破坏表面质量，对超精密加工完全有害。记忆：超精密\\"讨厌积屑瘤\\"。"},{"id":64,"type":"judge","category":"精密切削","difficulty":2,"question":"工件的加工精度是由成形运动的精度决定的。","options":[],"answer":true,"explanation":"正确。成形运动精度是决定工件加工精度的主要因素之一。记忆：精度\\"看成形运动\\"。"},{"id":65,"type":"judge","category":"精密切削","difficulty":2,"question":"两把金刚石车刀在相同进给量下超精密车削时，切削刃钝圆半径小的金刚石车刀加工表面粗糙度值较小。","options":[],"answer":true,"explanation":"正确。切削刃钝圆半径越小，切削越锋利，残留面积越小，表面粗糙度值越小。记忆：钝圆半径\\"越小越光\\"。"},{"id":66,"type":"judge","category":"精密磨削","difficulty":3,"question":"两接触表面粗糙度越小，微观凹凸越不明显，表面相互运动磨损越小。","options":[],"answer":false,"explanation":"错误。表面过于光滑会导致分子吸附力增大，反而容易产生粘着磨损，存在最佳粗糙度范围。记忆：表面\\"不是越光越好\\"。"},{"id":67,"type":"judge","category":"精密磨削","difficulty":1,"question":"磨粒的粒度号越大，粒径越大。","options":[],"answer":false,"explanation":"错误。粒度号越大，磨粒越细，粒径越小。记忆：粒度号\\"越大越小\\"。"},{"id":68,"type":"judge","category":"精密磨削","difficulty":2,"question":"抛光可以提高工件形状精度和尺寸精度。","options":[],"answer":false,"explanation":"错误。抛光只能改善表面粗糙度，不能提高形状精度和尺寸精度。记忆：抛光\\"只改善粗糙度\\"。"},{"id":69,"type":"judge","category":"精密切削","difficulty":2,"question":"金刚石刀具是目前世界上已知最硬的材料，可以切削任何金属材料。","options":[],"answer":false,"explanation":"错误。金刚石虽然最硬，但不能加工钢铁材料，因为会发生化学反应。记忆：金刚石\\"怕铁\\"。"},{"id":70,"type":"judge","category":"精密磨削","difficulty":2,"question":"精密抛光时磨粒对工件的作用力很小，即使抛光脆性材料也不会产生裂纹。","options":[],"answer":true,"explanation":"正确。精密抛光作用力极小，不会超过脆性材料的断裂韧性，因此不会产生裂纹。记忆：精密抛光\\"无裂纹\\"。"},{"id":71,"type":"judge","category":"精密磨削","difficulty":1,"question":"人是非常重要的粉尘源，在精密加工的洁净房内要尽量减少人的活动或动作幅度。","options":[],"answer":true,"explanation":"正确。人体是重要的污染源，会产生粉尘、皮屑等，洁净房内要限制人员活动。记忆：洁净房\\"少走动\\"。"},{"id":72,"type":"judge","category":"精密磨削","difficulty":2,"question":"砂轮的组织或浓度越高，磨削的效率越高，磨削质量越好。","options":[],"answer":false,"explanation":"错误。浓度过高会导致磨削力增大、温度升高、容易堵塞，反而降低磨削质量。记忆：浓度\\"不是越高越好\\"。"},{"id":73,"type":"judge","category":"精密磨削","difficulty":2,"question":"磨粒的硬度越高，砂轮的硬度越高。","options":[],"answer":false,"explanation":"错误。砂轮硬度取决于结合剂强度，与磨粒硬度无关。砂轮硬度是指磨粒脱落的难易程度。记忆：砂轮硬度看\\"结合剂\\"。"},{"id":74,"type":"single","category":"电火花加工","difficulty":2,"question":"电火花线切割的微观过程可分为四个连续阶段:a)电极材料的抛出;b)极间介质的电离、击穿，形成放电通道;c)极间介质的消电离;d)介质热分解、电极材料熔化、气化热膨胀。这四个阶段的排列顺序为(        )。","options":["A. abcd","B. bdac","C. acdb","D. cbad"],"answer":"B","explanation":"电火花线切割微观过程顺序：先电离击穿形成放电通道(b)，再热分解材料熔化气化(d)，然后材料抛出(a)，最后消电离(c)。记忆口诀：\\"击热抛离\\"。"},{"id":75,"type":"single","category":"电火花加工","difficulty":3,"question":"以下关于电火花加工表面变质层叙述不正确的是(        )。","options":["A. 淬火钢的热影响层强度比基材层低，未淬火钢的热影响层强度比基材层高。","B. 熔化层硬度高、耐磨性好，但残余拉应力大容易产生微裂纹，疲劳强度低，与热影响层的结合力也比较弱，容易脱落。","C. 熔化层、热影响层和基材层三者之间都有明显分界线。","D. 熔化层和热影响层的厚度随脉冲能量的增加而加厚。"],"answer":"C","explanation":"熔化层、热影响层和基材层之间是渐变过渡的，没有明显分界线。说有明显分界线是错误的。记忆：变质层\\"渐变无界\\"。"},{"id":76,"type":"single","category":"电火花加工","difficulty":2,"question":"电火花加工过程中，工件材料的(        )，工件加工速度越快。","options":["A. 气化热愈高","B. 导热系数愈小","C. 熔点愈高","D. 沸点愈高"],"answer":"B","explanation":"导热系数愈小，热量越集中在放电点，材料越容易熔化气化去除，加工速度越快。其他因素如熔点、沸点、气化热越高反而越难加工。记忆：导热差\\"加工快\\"。"},{"id":77,"type":"single","category":"电火花加工","difficulty":3,"question":"以下关于电火花加工精度叙述不正确的是(        )。","options":["A. 二次放电使型腔加工深度方向产生斜度和加工棱角棱边变钝。","B. 贯穿型孔电火花加工不会明显影响型孔的加工精度。","C. 为了提高加工精度,应采用较弱小的加工规准,缩小放电间隙，使加工过程稳定。","D. 无论慢走丝，还是快走丝，电极丝的损耗会明显影响切割加工的精度。"],"answer":"D","explanation":"慢走丝电极丝是一次性使用，损耗对精度影响小；快走丝电极丝反复使用，损耗会影响精度。说都不影响是错误的。记忆：慢走丝\\"精度高\\"。"},{"id":78,"type":"single","category":"电火花加工","difficulty":2,"question":"电火花加工过程中，负极性加工主要适用于(        )。","options":["A. 长脉冲-粗加工","B. 短脉冲-粗加工","C. 短脉冲-精加工","D. 长脉冲-精加工"],"answer":"A","explanation":"负极性加工（工件接负极）适用于长脉冲粗加工，可利用覆盖效应减少电极损耗。正极性适合精加工。记忆：负极性\\"粗加工\\"。"},{"id":79,"type":"single","category":"电火花加工","difficulty":2,"question":"不能使用电火花线切割加工的材料为(        )。","options":["A. 石墨","B. 铝","C. 硬质合金","D. 大理石"],"answer":"D","explanation":"电火花加工只能加工导电材料，大理石是绝缘体，不能用电火花加工。石墨、铝、硬质合金都导电。记忆：电火花\\"只切导体\\"。"},{"id":80,"type":"single","category":"电火花加工","difficulty":2,"question":"电火花加工时单个脉冲能量越大，加工表面粗糙度值越(        )。","options":["A. 没有关系","B. 小","C. 大","D. 不确定"],"answer":"C","explanation":"脉冲能量越大，放电蚀除的凹坑越大，表面粗糙度值越大。能量和粗糙度成正比。记忆：能量大\\"粗糙度大\\"。"},{"id":81,"type":"single","category":"电火花加工","difficulty":2,"question":"电火花加工与线切割加工的不同点在于(        )。","options":["A. 最小角部半径不受限制","B. 主要加工导电材料","C. 可以加工盲孔","D. 加工速度慢"],"answer":"C","explanation":"电火花成形加工可以加工盲孔，而线切割只能加工通孔（贯穿型孔）。这是两者的主要区别。记忆：成形可\\"加工盲孔\\"。"},{"id":82,"type":"single","category":"电火花加工","difficulty":2,"question":"电火花加工过程中，工具电极的(        )，工具电极的消耗越少","options":["A. 导热系数愈大","B. 熔点愈低","C. 沸点愈低","D. 气化热愈低"],"answer":"A","explanation":"导热系数愈大，热量越容易散失，电极温度越低，损耗越少。熔点、沸点、气化热越低反而损耗越大。记忆：导热好\\"损耗少\\"。"},{"id":83,"type":"single","category":"电火花加工","difficulty":2,"question":"现在大中型电火花加工机床采用(        )电源","options":["A. 弛张式脉冲","B. 晶体管式脉冲","C. 以上都不是","D. 晶闸管式脉冲"],"answer":"D","explanation":"大中型电火花机床采用晶闸管式脉冲电源，功率大、效率高。中小型采用晶体管式。记忆：大中型用\\"晶闸管\\"。"},{"id":84,"type":"single","category":"电火花加工","difficulty":2,"question":"电火花加工过程中，以下关于银钨电极叙述正确的是(        )。","options":["A. 硬度高，加工性能不好","B. 资源稀缺，价格贵","C. 以上都对","D. 熔点高，消耗少"],"answer":"C","explanation":"银钨电极熔点高、消耗少，但硬度高加工困难，且资源稀缺价格贵。以上都对。记忆：银钨\\"好但贵\\"。"},{"id":85,"type":"single","category":"电火花加工","difficulty":2,"question":"电火花加工，表面层受高温作用后又迅速冷却而产生(        )。","options":["A. 没有残余应力","B. 残余压应力","C. 残余拉应力","D. 不确定"],"answer":"C","explanation":"电火花加工表面受高温后急冷，产生残余拉应力，容易导致微裂纹。拉应力是有害的。记忆：电火花\\"拉应力\\"。"},{"id":86,"type":"single","category":"电火花线切割","difficulty":2,"question":"慢走丝线切割机床采用(        )","options":["A. 钨钼丝电极丝，乳液工作液","B. 黄铜丝电极丝，去离子水工作液","C. 黄铜丝电极丝，乳液工作液","D. 钨钼丝电极丝，去离子水工作液"],"answer":"B","explanation":"慢走丝线切割采用黄铜丝作为电极丝（一次性使用），去离子水作为工作液。快走丝用钨钼丝和乳化液。记忆：慢走丝\\"黄铜+去离子水\\"。"},{"id":87,"type":"single","category":"电火花加工","difficulty":1,"question":"脉冲宽度的单位是(        )。","options":["A. μs","B. mm","C. cm","D. s"],"answer":"A","explanation":"脉冲宽度是微秒级的时间参数，单位是μs（微秒）。毫秒级太长，纳秒级太短。记忆：脉冲宽度\\"微秒级\\"。"},{"id":88,"type":"single","category":"电火花加工","difficulty":2,"question":"以下(        )不是电火花加工的必备条件。","options":["A. 液体工作介质","B. 石墨电极","C. 脉冲电源","D. 一定的放电间隙"],"answer":"B","explanation":"电火花加工需要脉冲电源、液体介质、放电间隙，电极材料可以是铜、石墨等多种，不一定是石墨。记忆：三必备条件\\"不含石墨\\"。"},{"id":89,"type":"single","category":"电火花线切割","difficulty":2,"question":"电火花线切割机床使用的脉冲电源输出的是(        )。","options":["A. 频率可变的交流直流脉冲","B. 固定频率的交流脉冲电源","C. 固定频率的单向直流脉冲","D. 频率可变的单向直流脉冲"],"answer":"D","explanation":"线切割脉冲电源输出频率可变的单向直流脉冲，以适应不同加工要求。固定频率不能调节。记忆：线切割电源\\"频率可变\\"。"},{"id":90,"type":"single","category":"电火花线切割","difficulty":2,"question":"电火花线切割加工过程中，下列四种说法，(        )是正确的。","options":["A. 只存在电火花放电一种放电状态","B. 工作液一般采用水基工作液","C. 电源可选直流脉冲或交流电源","D. 工具电极丝高速运动，没有损耗"],"answer":"B","explanation":"线切割工作液一般采用水基工作液（去离子水或乳化液），有利于冷却和排屑。记忆：线切割\\"水基工作液\\"。"},{"id":91,"type":"single","category":"电火花线切割","difficulty":2,"question":"线切割加工中，采用水基工作液的原因不是(        )。","options":["A. 正极性加工不需要油类工作液的覆盖效应。","B. 改善消电离冷却效果。","C. 减少电极丝的损耗。","D. 提高加工精度。"],"answer":"C","explanation":"水基工作液主要优点是冷却好、排屑好、精度高，但对减少电极丝损耗没有明显作用。记忆：水基\\"不减损耗\\"。"},{"id":92,"type":"single","category":"电火花加工","difficulty":3,"question":"电火花加工过程中，(        )不是吸附效应产生的条件。","options":["A. 油类介质","B. 足够高温度","C. 正极性加工","D. 足够时间"],"answer":"C","explanation":"吸附效应需要油类介质、足够温度和时间，与极性无关。正极性加工是覆盖效应的条件。记忆：吸附效应\\"三条件\\"。"},{"id":93,"type":"single","category":"电火花线切割","difficulty":2,"question":"快走丝线切割机床采用(        )","options":["A. 黄铜丝电极丝，乳液工作液","B. 钨钼丝电极丝，去离子水工作液","C. 钨钼丝电极丝，乳液工作液","D. 黄铜丝电极丝，去离子水工作液"],"answer":"C","explanation":"快走丝线切割采用钨钼丝（可反复使用）和乳液工作液。慢走丝用黄铜丝和去离子水。记忆：快走丝\\"钨钼+乳液\\"。"},{"id":94,"type":"single","category":"电火花加工","difficulty":2,"question":"下列四种工件材料，(        )不适合用电火花加工。","options":["A. 45号钢","B. 光学玻璃","C. 不锈钢","D. 铜"],"answer":"B","explanation":"电火花只能加工导电材料，光学玻璃是绝缘体，不能用电火花加工。45号钢、不锈钢、铜都导电。记忆：电火花\\"只切导体\\"。"},{"id":95,"type":"single","category":"电火花线切割","difficulty":3,"question":"电火花线切割采用正极性加工的主要目的是(        )。","options":["A. 降低表面粗糙度值","B. 提高加工速度","C. 提高加工精度","D. 减少工具电极损耗"],"answer":"C","explanation":"正极性加工（工件接正极）可提高加工精度，是线切割常用的加工方式。负极性用于粗加工。记忆：正极性\\"精加工\\"。"},{"id":96,"type":"single","category":"电火花线切割","difficulty":2,"question":"下列(        )不属于高速走丝电火花线切割加工的特点。","options":["A. 电极丝双向移动","B. 工作液为去离子水","C. 运丝速度为8-10m/s","D. 加工精度±0.01mm"],"answer":"B","explanation":"高速走丝（快走丝）线切割使用乳液工作液，不是去离子水。去离子水是慢走丝使用的。记忆：快走丝用\\"乳液\\"。"},{"id":97,"type":"single","category":"电火花加工","difficulty":2,"question":"选择电火花粗加工条件的主要因素是(        )。","options":["A. 放电间隙","B. 加工速度","C. 加工精度","D. 放电面积"],"answer":"B","explanation":"粗加工主要追求加工速度（生产率），精加工才主要考虑精度。记忆：粗加工\\"看速度\\"。"},{"id":98,"type":"single","category":"电火花加工","difficulty":2,"question":"电火花线切割的微观过程可分为电极材料的抛出;极间介质的电离、击穿，形成放电通道;极间介质的消电离;介质热分解、电极材料熔化、气化热膨胀。这四个阶段中，间隙电压最高的是(        )。","options":["A. 极间介质的消电离","B. 极间介质的电离、击穿，形成放电通道","C. 电极材料的抛出","D. 介质热分解、电极材料熔化、气化热膨胀"],"answer":"B","explanation":"电离击穿阶段需要最高电压来击穿介质，形成放电通道。其他阶段电压较低。记忆：击穿\\"电压最高\\"。"},{"id":99,"type":"single","category":"电火花加工","difficulty":3,"question":"以下关于电火花加工速度叙述不正确的是(        )。","options":["A. 工作液流动压力越大，电蚀产物排除效果越好，加工速度越高。","B. 脉冲宽度、峰值电流增加可以提高加工速度，但过大反而会导致加工速度降低。","C. 加工面积过小,单位面积上脉冲放电过分集中,将大幅降低加工速度。","D. 根据间隙状态,决定电极是否\\"抬刀\\",避免不必要抬刀动作,提高加工速度。"],"answer":"A","explanation":"工作液流动压力过大会干扰放电过程，反而降低加工速度，需要适当压力。不是越大越好。记忆：工作液压力\\"适中\\"。"},{"id":100,"type":"single","category":"电火花加工","difficulty":2,"question":"对于电火花加工，属于难加工材料的是(        )。","options":["A. 硬质合金","B. 钼","C. 淬火钢","D. 不锈钢"],"answer":"B","explanation":"钼的熔点很高（2620℃），电火花加工困难，属于难加工材料。硬质合金、淬火钢、不锈钢相对容易。记忆：钼\\"难加工\\"。"},{"id":101,"type":"single","category":"电火花线切割","difficulty":2,"question":"电火花线切割加工一般安排在(        )。","options":["A. 淬火之后，磨削之前","B. 淬火与磨削之前","C. 淬火之前，磨削之后","D. 淬火与磨削之后"],"answer":"D","explanation":"线切割加工一般安排在淬火和磨削之后，因为线切割可以加工淬硬材料，且精度高。记忆：线切割\\"最后加工\\"。"},{"id":102,"type":"single","category":"电火花加工","difficulty":2,"question":"在给定加工面上由于电蚀产物的介入而再次进行的非正规放电称为(        )。","options":["A. 二次放电","B. 拉弧","C. 火花放电","D. 电弧放电"],"answer":"A","explanation":"二次放电是电蚀产物导致的非正规放电，会影响加工精度，产生斜度。记忆：二次放电\\"影响精度\\"。"},{"id":103,"type":"single","category":"电火花线切割","difficulty":2,"question":"电火花线切割加工中，工作液不具有的性能是(        )。","options":["A. 绝缘性能","B. 冷却性能","C. 洗涤性能","D. 润滑性能"],"answer":"D","explanation":"线切割工作液需要绝缘、冷却、洗涤性能，但不需要润滑性能。记忆：线切割工作液\\"三性能\\"。"},{"id":104,"type":"single","category":"电火花加工","difficulty":3,"question":"以下关于电火花加工表面粗糙度叙述不正确的是(        )。","options":["A. 工作液越干净，越有利于得到较小的表面粗糙度Ra值。","B. 加工速度越快，加工表面的粗糙度值Ra越大。","C. 脉冲电流和脉冲宽度越大，加工表面的粗糙度值Ra越大。","D. 工件材料熔点越高，加工表面的粗糙度值Ra越大。"],"answer":"D","explanation":"工件材料熔点越高，蚀除越困难，但与表面粗糙度无直接正比关系。其他因素如脉冲能量影响更大。记忆：粗糙度\\"主要看能量\\"。"},{"id":105,"type":"single","category":"电火花加工","difficulty":2,"question":"下列叙述不正确的是(        )。","options":["A. 脉冲间隔增大，加工速度提高","B. 脉冲宽度增大，加工速度提高","C. 脉冲间隔过小，放电间隙可能来不及消电离，加工稳定性可能变差，加工速度降低","D. 峰值电流增大，加工速度提高"],"answer":"A","explanation":"脉冲间隔增大，单位时间内放电次数减少，加工速度降低，不是提高。记忆：间隔大\\"速度低\\"。"},{"id":106,"type":"single","category":"电火花线切割","difficulty":2,"question":"经济型电火花线切割机床所用电动机是(        )。","options":["A. 步进电动机","B. 伺服电动机","C. 直线电动机","D. 交流电动机"],"answer":"A","explanation":"经济型线切割机床采用步进电动机驱动，成本低、结构简单。伺服电动机精度更高但成本也高。记忆：经济型用\\"步进电机\\"。"},{"id":107,"type":"single","category":"电火花线切割","difficulty":2,"question":"电火花线切割不能加工的材料或型孔是(        )。","options":["A. 方孔","B. 异形孔","C. 盲孔","D. 淬火钢"],"answer":"C","explanation":"线切割电极丝必须穿过工件，只能加工通孔，不能加工盲孔。方孔、异形孔、淬火钢都可以加工。记忆：线切割\\"只能通孔\\"。"},{"id":108,"type":"single","category":"电火花线切割","difficulty":3,"question":"电火花线切割加工较厚的工件时，要保证加工的稳定，放电间隙要大，所以(        )。","options":["A. 脉冲宽度取较小值，脉冲间隔取大值","B. 脉冲宽度和脉冲间隔都取小值","C. 脉冲宽度和脉冲间隔都取大值","D. 脉冲宽度取较大值，脉冲间隔取小值"],"answer":"C","explanation":"加工厚工件需要大放电间隙，应增大脉冲宽度和脉冲间隔，保证排屑和消电离。记忆：厚工件\\"双增大\\"。"},{"id":109,"type":"single","category":"电火花加工","difficulty":2,"question":"电火花加工过程中，正极性加工主要适用于(        )。","options":["A. 长脉冲-粗加工","B. 短脉冲-粗加工","C. 长脉冲-精加工","D. 短脉冲-精加工"],"answer":"D","explanation":"正极性加工（工件接正极）适用于短脉冲精加工，可获得较好的表面质量。负极性用于粗加工。记忆：正极性\\"精加工\\"。"},{"id":110,"type":"single","category":"电火花线切割","difficulty":2,"question":"线切割加工中数控系统的补偿功能主要是用来补偿机械系统产生的(        )。","options":["A. 振动","B. 温度变化","C. 电场变化","D. 尺寸误差"],"answer":"D","explanation":"数控系统的补偿功能主要用于补偿机械传动误差、电极丝半径等造成的尺寸误差。记忆：补偿\\"尺寸误差\\"。"},{"id":111,"type":"single","category":"电火花线切割","difficulty":2,"question":"电火花线切割加工中，当工作液的绝缘性能太高时会(        )。","options":["A. 产生电解","B. 排屑困难","C. 放电间隙小","D. 切割速度缓慢"],"answer":"D","explanation":"绝缘性能太高，击穿困难，放电不充分，导致切割速度缓慢。需要适当绝缘性。记忆：绝缘太高\\"速度慢\\"。"},{"id":112,"type":"single","category":"电火花线切割","difficulty":3,"question":"关于线切割加工叙述不正确的是(        )。","options":["A. 熔化层、热影响层和基材层三者之间都有明显分界线。","B. 线切割加工是属于电火花的正极性加工。","C. 淬火钢的热影响层强度比基材层低，未淬火钢的热影响层强度比基材层高。","D. 熔化层硬度高、耐磨性好，但残余拉应力大容易产生微裂纹，疲劳强度低，与热影响层的结合力也比较弱，容易脱落。"],"answer":"A","explanation":"熔化层、热影响层和基材层之间是渐变过渡的，没有明显分界线。说有明显分界线是错误的。记忆：变质层\\"渐变无界\\"。"},{"id":113,"type":"single","category":"电火花加工","difficulty":2,"question":"电火花加工过程中，以下关于铜电极叙述正确的是(        )。","options":["A. 导热性好，消耗少","B. 强度、硬度适中，加工性能好","C. 紫铜比黄铜消耗少，但价格更贵。","D. 以上都对"],"answer":"D","explanation":"铜电极导热好、消耗少、易加工，紫铜比黄铜性能更好但价格更贵。以上都对。记忆：铜电极\\"好但贵\\"。"},{"id":114,"type":"single","category":"电火花线切割","difficulty":2,"question":"电极丝的进给速度大于材料的蚀除速度，致使电极丝与工件接触，不能正常放电，称为(        )。","options":["A. 放电加工","B. 短路","C. 击穿","D. 电极损耗"],"answer":"B","explanation":"电极丝与工件接触形成短路，不能正常放电，需要调整进给速度。记忆：短路\\"进给太快\\"。"},{"id":115,"type":"single","category":"电火花加工","difficulty":2,"question":"电火花加工中脉冲间隔的主要作用是(        )","options":["A. 恢复间隙绝缘","B. 提高加工速度","C. 减少工具损耗","D. 降低表面粗糙度值"],"answer":"A","explanation":"脉冲间隔的作用是让工作液恢复绝缘状态，为下一次放电做准备。记忆：间隔\\"恢复绝缘\\"。"},{"id":116,"type":"single","category":"电火花加工","difficulty":2,"question":"工具电极接脉冲电源负极的电火花加工叫(        )。","options":["A. 阴极性加工","B. 脉冲正负极性加工","C. 负极性加工","D. 正极性加工"],"answer":"D","explanation":"工具电极接负极、工件接正极称为正极性加工（正极性加工中工件为正极）。记忆：正极性\\"工件为正\\"。"},{"id":117,"type":"single","category":"电火花线切割","difficulty":2,"question":"线切割加工中，(        )属于减小电极丝损耗的因素。","options":["A. 以上都是。","B. 电极丝快速离开放电区域并被冷却。","C. 电极丝采用钨钼等高熔点材料。","D. 采用短脉冲的正极性加工。"],"answer":"A","explanation":"以上因素都能减小电极丝损耗：快速冷却、高熔点材料、正极性加工。记忆：减损耗\\"三方法\\"。"},{"id":118,"type":"single","category":"电火花加工","difficulty":2,"question":"电火花加工型腔，工具电极常用的材料有(        )。","options":["A. 石墨、紫铜","B. 钨、钼","C. 铜、钢","D. 钨、铜"],"answer":"A","explanation":"电火花型腔加工常用石墨和紫铜作为电极材料，加工性能好、损耗小。钨钼用于线切割。记忆：型腔用\\"石墨紫铜\\"。"},{"id":119,"type":"single","category":"电火花加工","difficulty":2,"question":"(        )不是电火花加工的优点。","options":["A. 可以改进结构设计和改善结构的工艺性","B. 可以加工复杂形状的零件","C. 易于实现加工过程自动化","D. 可以加工陶瓷、塑料"],"answer":"D","explanation":"电火花只能加工导电材料，陶瓷和塑料是绝缘体，不能用电火花加工。其他都是优点。记忆：电火花\\"只切导体\\"。"},{"id":120,"type":"single","category":"电火花加工","difficulty":2,"question":"电火花加工过程中，以下关于石墨电极叙述正确的是(        )。","options":["A. 加工表面的粗糙度偏大","B. 以上都对","C. 熔点高，消耗少","D. 脆性大，加工性能不好"],"answer":"B","explanation":"石墨电极熔点高、消耗少，但脆性大、加工表面粗糙度偏大。以上都对。记忆：石墨\\"好但脆\\"。"},{"id":121,"type":"single","category":"电火花加工","difficulty":2,"question":"不是对电火花脉冲电源输出要求的是(        )。","options":["A. 加工过程稳定","B. 工具损耗尽可能小","C. 电流要大","D. 工艺范围广"],"answer":"C","explanation":"脉冲电源要求稳定、损耗小、工艺范围广，但不是电流越大越好，要根据加工要求选择。记忆：电源\\"不是越大越好\\"。"},{"id":122,"type":"single","category":"电火花加工","difficulty":2,"question":"现在中小型电火花加工机床采用(        )电源","options":["A. 弛张式脉冲","B. 晶体管式脉冲","C. 晶闸管式脉冲","D. 以上都不是"],"answer":"B","explanation":"中小型电火花机床采用晶体管式脉冲电源，控制精度高、响应快。大中型用晶闸管式。记忆：中小型用\\"晶体管\\"。"},{"id":123,"type":"single","category":"电火花加工","difficulty":2,"question":"对于电火花加工的描述不正确的是(        )。","options":["A. 电火花加工与机械加工不同","B. 加工表面有变质层","C. 存在电极损耗","D. 加工速度较快"],"answer":"D","explanation":"电火花加工速度较慢，这是它的缺点之一，不是优点。其他描述正确。记忆：电火花\\"速度慢\\"。"},{"id":124,"type":"single","category":"电火花线切割","difficulty":3,"question":"电火花线切割加工较厚的工件时，电极丝的进口宽度与出口宽度相比(        )。","options":["A. 进口宽度大","B. 出口宽度大","C. 不一定","D. 相同"],"answer":"A","explanation":"加工厚工件时，进口处工作液充分、冷却好，蚀除量大，所以进口宽度大于出口宽度。记忆：厚工件\\"进口宽\\"。"},{"id":125,"type":"single","category":"电火花加工","difficulty":1,"question":"电火花加工必须采用(        )电源。","options":["A. 直流","B. 都可以","C. 脉冲","D. 交流"],"answer":"C","explanation":"电火花加工必须采用脉冲电源，使放电能量集中在极短时间内，产生高温蚀除材料。记忆：电火花\\"必须脉冲\\"。"},{"id":126,"type":"single","category":"电火花线切割","difficulty":3,"question":"关于线切割加工导轮组件叙述不正确的是(        )。","options":["A. 导轮对电极丝起定位和防止振动作用，要采用耐磨材料加工,慢走丝机床常选用人造宝石。","B. 尽量减轻导轮质量,减少换向时电极丝与导轮间的滑动摩擦，提高其使用寿命。","C. 导轮有较高的运动精度, 径向偏摆和轴向窜动不得超过1um。","D. 导轮组件有非常高的密封措施，防止放电蚀除产物和杂质进入导轮轴承影响运动精度。"],"answer":"C","explanation":"导轮精度要求高，但径向偏摆和轴向窜动一般在几微米范围，不是不超过1μm。记忆：导轮精度\\"微米级\\"。"},{"id":127,"type":"single","category":"电火花加工","difficulty":3,"question":"电火花加工过程中，(        )进行自动控制更有利于提高加工效率和质量。","options":["A. 脉冲间隔","B. \\"抬刀\\"动作","C. 加工间隙","D. 以上都是"],"answer":"A","explanation":"脉冲间隔的自动控制对加工效率和质量影响最大，是主要的控制参数。记忆：控制主要看\\"脉冲间隔\\"。"},{"id":128,"type":"single","category":"电火花线切割","difficulty":2,"question":"电火花线切割加工机床脉冲电源与电火花成形加工机床脉冲电源(        )。","options":["A. 原理和性能要求都不相同","B. 原理不同，性能要求相同","C. 原理相同，性能要求不相同","D. 原理和性能要求都相同"],"answer":"C","explanation":"两者原理相同（都是脉冲放电），但性能要求不同（线切割要求更精细）。记忆：原理相同\\"要求不同\\"。"},{"id":129,"type":"single","category":"电火花加工","difficulty":2,"question":"下列与电火花加工速度无关的是(        )。","options":["A. 工件的硬度","B. 工件的汽化热","C. 工件的比热","D. 工件的熔点"],"answer":"A","explanation":"电火花加工靠热能蚀除材料，与工件硬度无关，与熔点、汽化热、比热等热学性能有关。记忆：电火花\\"不看硬度\\"。"},{"id":130,"type":"single","category":"电火花加工","difficulty":2,"question":"下列描述哪一项不是电火花成形粗加工要求的(        )。","options":["A. 较高的生产率和低电极损耗","B. 电流与工件无关","C. 高峰值电流","D. 宽脉冲"],"answer":"B","explanation":"粗加工需要高峰值电流、宽脉冲以获得高生产率，但电流要根据工件情况选择，不是与工件无关。记忆：粗加工\\"看工件选电流\\"。"},{"id":131,"type":"judge","category":"电火花加工","difficulty":2,"question":"电火花加工工具材料一定比工件材料软。","options":[],"answer":false,"explanation":"错误。电火花加工靠热能蚀除，不要求工具比工件软，工具材料可以是铜、石墨等。记忆：电火花\\"不看硬度\\"。"},{"id":132,"type":"judge","category":"电火花加工","difficulty":2,"question":"工具电极的损耗对尺寸精度有影响，对形状精度没有影响。","options":[],"answer":false,"explanation":"错误。电极损耗既影响尺寸精度，也影响形状精度（如棱角变钝、形状畸变）。记忆：损耗\\"两精度都影响\\"。"},{"id":133,"type":"judge","category":"电火花加工","difficulty":1,"question":"特种加工可以达到亚微米、豪微米级加工精度。","options":[],"answer":true,"explanation":"正确。特种加工（如电火花、激光等）可以达到很高的加工精度，包括亚微米级。记忆：特种加工\\"高精度\\"。"},{"id":134,"type":"judge","category":"电火花加工","difficulty":2,"question":"电火花加工表面与机械加工表面不同。","options":[],"answer":true,"explanation":"正确。电火花加工表面有熔化层、热影响层等变质层，表面形貌也不同于机械加工。记忆：电火花表面\\"有变质层\\"。"},{"id":135,"type":"judge","category":"电火花加工","difficulty":2,"question":"电火花和电化学加工是非接触加工，加工后的表面无残余应力。","options":[],"answer":false,"explanation":"错误。电火花加工表面受热后急冷会产生残余拉应力，电化学加工也可能有残余应力。记忆：电火花\\"有拉应力\\"。"},{"id":136,"type":"judge","category":"电火花加工","difficulty":1,"question":"脉冲电源能把直流电或交流电变成适应电火花加工需要的单向脉冲电源。","options":[],"answer":true,"explanation":"正确。脉冲电源的作用就是将直流或交流电转换成高频单向脉冲，满足电火花加工需要。记忆：脉冲电源\\"转换作用\\"。"},{"id":137,"type":"judge","category":"电火花线切割","difficulty":2,"question":"在慢走丝线切割加工中，由于电机丝不损耗，所以加工精度高。","options":[],"answer":false,"explanation":"错误。慢走丝电极丝是一次性使用，走丝慢且张力均匀，所以精度高，不是因为不损耗。记忆：慢走丝\\"精度高的原因\\"。"},{"id":138,"type":"judge","category":"电火花加工","difficulty":2,"question":"电火花加工表面和机械加工表面的加工痕迹不同。","options":[],"answer":true,"explanation":"正确。电火花表面是放电蚀除的凹坑，机械加工是切削痕迹，两者形貌不同。记忆：两种表面\\"形貌不同\\"。"},{"id":139,"type":"judge","category":"电火花加工","difficulty":2,"question":"电火花加工工具的尖角或凹角会精确复制在工件上。","options":[],"answer":false,"explanation":"错误。由于二次放电和放电间隙的影响，尖角会变圆，凹角会变大，不能精确复制。记忆：电火花\\"不能复制尖角\\"。"},{"id":140,"type":"judge","category":"电火花线切割","difficulty":2,"question":"一般来说快走丝线切割机床加工精度高于慢走丝线切割机床。","options":[],"answer":false,"explanation":"错误。慢走丝线切割精度高于快走丝，慢走丝精度可达±0.002mm，快走丝约±0.01mm。记忆：慢走丝\\"精度更高\\"。"},{"id":141,"type":"judge","category":"电火花加工","difficulty":2,"question":"电火花加工时，如果工具、工件的材料一样，则在放电加工中两极的蚀除量也一样。","options":[],"answer":false,"explanation":"错误。由于极性效应，即使材料相同，两极的蚀除量也不一样，与极性有关。记忆：极性效应\\"蚀除量不同\\"。"},{"id":142,"type":"judge","category":"电火花线切割","difficulty":2,"question":"低速走丝的排屑条件较差，要采用高压喷液加工进行改善排屑效果。","options":[],"answer":true,"explanation":"正确。慢走丝加工深窄缝时排屑困难，需要高压喷液改善排屑。记忆：慢走丝\\"需高压喷液\\"。"},{"id":143,"type":"judge","category":"电火花线切割","difficulty":2,"question":"电火花线切割的加工速度随着脉冲间隔的增大而增大。","options":[],"answer":false,"explanation":"错误。脉冲间隔增大，单位时间放电次数减少，加工速度降低。记忆：间隔大\\"速度低\\"。"},{"id":144,"type":"judge","category":"电火花加工","difficulty":2,"question":"电火花加工型腔精度要求比较高时，可以通过更换工具电极实现。","options":[],"answer":true,"explanation":"正确。可以采用粗加工电极和精加工电极分别加工，提高型腔精度。记忆：型腔加工\\"双电极\\"。"},{"id":145,"type":"judge","category":"电火花线切割","difficulty":2,"question":"电火花线切割可以加工圆孔，但不能加工方孔。","options":[],"answer":false,"explanation":"错误。线切割可以加工任意形状的通孔，包括圆孔、方孔、异形孔等。记忆：线切割\\"形状不限\\"。"},{"id":146,"type":"judge","category":"电火花加工","difficulty":2,"question":"从提高生产率和减小工具损耗角度看，极性效应越显著越好，所以电火花加工一般采用单向脉冲电源。","options":[],"answer":true,"explanation":"正确。极性效应显著可以减小工具损耗，单向脉冲电源有利于利用极性效应。记忆：极性效应\\"减损耗\\"。"},{"id":147,"type":"judge","category":"电火花线切割","difficulty":2,"question":"降低快走丝线切割速度会减小表面粗糙度值Ra。","options":[],"answer":true,"explanation":"正确。降低切割速度，单位面积放电能量减小，表面粗糙度值减小。记忆：速度低\\"粗糙度小\\"。"},{"id":148,"type":"judge","category":"电火花加工","difficulty":2,"question":"电火花加工的表面粗糙度和加工速度之间存在很大的矛盾，表面粗糙度精度提高，加工速度要明显下降。","options":[],"answer":true,"explanation":"正确。这是电火花加工的基本矛盾：要提高表面质量必须减小脉冲能量，但会降低加工速度。记忆：电火花\\"质量速度矛盾\\"。"},{"id":149,"type":"judge","category":"电火花加工","difficulty":2,"question":"电火花加工淬硬钢比未淬硬钢更容易。","options":[],"answer":true,"explanation":"正确。电火花加工与材料硬度无关，淬硬钢导热系数低，热量集中，反而更容易加工。记忆：淬硬钢\\"反而好加工\\"。"},{"id":150,"type":"judge","category":"电火花加工","difficulty":2,"question":"电火花成形加工主要用于金属型腔加工。","options":[],"answer":true,"explanation":"正确。电火花成形加工主要用于加工各种形状复杂的型腔、型孔。记忆：成形加工\\"型腔型孔\\"。"},{"id":151,"type":"judge","category":"电火花加工","difficulty":1,"question":"电火花加工电源的作用是把直流或交流电转换成一定频率的单向脉冲电源。","options":[],"answer":true,"explanation":"正确。这是脉冲电源的基本功能，将直流或交流电转换成一定频率的单向脉冲电源。记忆：脉冲电源\\"转换功能\\"。"},{"id":152,"type":"judge","category":"电火花线切割","difficulty":2,"question":"快速走丝线切割表面粗糙度值Ra比慢走丝切割表面粗糙度值低。","options":[],"answer":false,"explanation":"错误。慢走丝加工精度高、表面粗糙度值小（更光滑），快走丝粗糙度值大。记忆：慢走丝\\"更光滑\\"。"},{"id":153,"type":"judge","category":"电火花线切割","difficulty":3,"question":"线切割加工的工件越厚,其加工表面粗糙度的数值越小。","options":[],"answer":true,"explanation":"正确。工件越厚，放电通道越长，能量分布越均匀，表面粗糙度数值越小。记忆：厚工件\\"粗糙度小\\"。"},{"id":154,"type":"judge","category":"电火花加工","difficulty":2,"question":"电火花精加工时，工具电极的表面粗糙度也将影响加工材料的表面粗糙度。","options":[],"answer":true,"explanation":"正确。精加工时放电间隙小，电极表面形貌会复印到工件上。记忆：精加工\\"复印效应\\"。"},{"id":155,"type":"judge","category":"电火花加工","difficulty":2,"question":"电火花成形加工主要用于金属冲模加工。","options":[],"answer":false,"explanation":"错误。电火花成形主要用于型腔加工，线切割才主要用于冲模加工。记忆：成形\\"型腔\\"，线切割\\"冲模\\"。"},{"id":156,"type":"judge","category":"电火花加工","difficulty":2,"question":"电火花加工时工件材料对加工表面粗糙度没有影响，而机械加工有影响。","options":[],"answer":false,"explanation":"错误。电火花加工表面粗糙度也受工件材料影响，不同材料蚀除特性不同。记忆：粗糙度\\"受材料影响\\"。"},{"id":157,"type":"judge","category":"电火花加工","difficulty":2,"question":"电极的制造精度与加工对象要求的精度一样。","options":[],"answer":false,"explanation":"错误。电极制造精度要高于加工对象精度，因为还有放电间隙等误差因素。记忆：电极精度\\"要更高\\"。"},{"id":158,"type":"judge","category":"电火花加工","difficulty":2,"question":"特种加工的出现，工件材料的加工性不再与其硬度、强度、韧性、脆性等有直接的关系。","options":[],"answer":true,"explanation":"正确。特种加工主要靠电能、热能等去除材料，与材料力学性能无直接关系。记忆：特种加工\\"不看力学性能\\"。"},{"id":159,"type":"judge","category":"电火花加工","difficulty":2,"question":"电火花加工机床的进给系统必须采用自动进给调节系统。","options":[],"answer":true,"explanation":"正确。电火花加工需要保持恒定的放电间隙，必须采用自动进给调节系统。记忆：电火花\\"自动进给\\"。"},{"id":160,"type":"judge","category":"电火花线切割","difficulty":2,"question":"线切割加工切割速度为单位时间内切削的工件材料体积或重量。","options":[],"answer":false,"explanation":"错误。线切割切割速度通常指单位时间内电极丝沿加工轨迹的移动速度（mm²/min），不是体积或重量。记忆：切割速度\\"面积单位\\"。"},{"id":161,"type":"judge","category":"电火花线切割","difficulty":2,"question":"慢走丝切割表面会有黑白相间的条纹问题。","options":[],"answer":false,"explanation":"错误。黑白相间的条纹是快走丝的问题（往复运丝），慢走丝单向走丝没有此问题。记忆：条纹\\"快走丝问题\\"。"},{"id":162,"type":"judge","category":"电火花加工","difficulty":2,"question":"被加工件淬火以后，其上的定位销孔、键槽，现可以用电火花加工。","options":[],"answer":true,"explanation":"正确。电火花可以加工淬硬材料，淬火后的孔、槽可以用电火花加工。记忆：电火花\\"可加工淬硬件\\"。"},{"id":163,"type":"judge","category":"电火花线切割","difficulty":2,"question":"电火花线切割加工和成形加工的放电蚀除机理基本相同。","options":[],"answer":true,"explanation":"正确。两者都是利用脉冲放电的热效应蚀除材料，机理基本相同。记忆：两种加工\\"机理相同\\"。"},{"id":164,"type":"judge","category":"电火花线切割","difficulty":2,"question":"电火花线切割即可以采用正极性加工，也可以采用负极性加工。","options":[],"answer":false,"explanation":"错误。线切割一般只采用正极性加工（工件接正极），不采用负极性加工。记忆：线切割\\"只用正极性\\"。"},{"id":165,"type":"judge","category":"电火花加工","difficulty":2,"question":"极性效应是由于电子和离子的自身重量导致运动速度和轰击作用大小的差异特性导致的。","options":[],"answer":true,"explanation":"正确。电子质量小、速度快，离子质量大、速度慢，导致正负极蚀除量不同，产生极性效应。记忆：极性效应\\"电子离子差异\\"。"},{"id":166,"type":"judge","category":"电火花线切割","difficulty":2,"question":"电火花线切割加工主要用于金属冲模加工。","options":[],"answer":true,"explanation":"正确。线切割特别适合加工冲模的凸模、凹模、固定板等。记忆：线切割\\"加工冲模\\"。"},{"id":167,"type":"judge","category":"电火花线切割","difficulty":2,"question":"电火花线切割机床不仅可以加工导电材料，还可以加工不导电材料。","options":[],"answer":false,"explanation":"错误。电火花线切割只能加工导电材料，不导电材料无法形成放电。记忆：线切割\\"只切导体\\"。"},{"id":168,"type":"judge","category":"电火花加工","difficulty":2,"question":"电火花成形即可以采用正极性加工，也可以采用负极性加工。","options":[],"answer":true,"explanation":"正确。电火花成形加工可根据需要选择正极性或负极性加工。记忆：成形\\"两种极性\\"。"},{"id":169,"type":"judge","category":"电火花加工","difficulty":2,"question":"覆盖效应一定要在油性工作介质中进行负极性加工才能减轻工具损耗。","options":[],"answer":true,"explanation":"正确。覆盖效应需要油类介质分解产生的碳黑沉积在工具表面，且在负极性加工中效果明显。记忆：覆盖效应\\"油类+负极性\\"。"},{"id":170,"type":"judge","category":"电火花加工","difficulty":2,"question":"电火花穿孔加工冲模时，冲模上的刃口斜度可以靠二次放电形成的锥度来保证。","options":[],"answer":true,"explanation":"正确。二次放电会在型孔侧壁产生锥度，可以利用这个特点加工冲模的刃口斜度。记忆：二次放电\\"可利用\\"。"},{"id":171,"type":"single","category":"电解加工","difficulty":2,"question":"电解磨削加工是(        )。","options":["A. 电化学复合加工","B. 阳极溶解","C. 化学抛光","D. 阴极沉积法"],"answer":"B","explanation":"电解磨削是利用阳极溶解作用去除材料的电化学加工方法。不是电化学复合加工。记忆：电解磨削\\"阳极溶解\\"。"},{"id":172,"type":"single","category":"电解加工","difficulty":2,"question":"电解加工型孔过程中，(        )。","options":["A. 要求工具电极作自动伺服进给","B. 要求工具电极作匀速等速进给","C. 要求工具电极作加速进给","D. 要求工具电极作超声振动"],"answer":"B","explanation":"电解加工要求工具电极匀速进给，保持恒定的加工间隙。不是伺服进给或加速进给。记忆：电解加工\\"匀速进给\\"。"},{"id":173,"type":"single","category":"电解加工","difficulty":3,"question":"下面选项不正确的是(        )。","options":["A. 电解加工中，加工速度与加工间隙成正比","B. 电解加工中，加工速度与电流效率成正比","C. 电解加工中，加工速度与工件材料的电化学当量成正比","D. 电解加工中，加工速度与电解液的导电率成正比"],"answer":"A","explanation":"加工速度与加工间隙成反比，间隙越大，电流密度越小，加工速度越低。说成正比是错误的。记忆：间隙大\\"速度低\\"。"},{"id":174,"type":"single","category":"电解加工","difficulty":2,"question":"电解加工常用电解液有三种，即氯化钠NaCI、硝酸钠NaNO3和(        )。","options":["A. 氯酸钠NaClO3","B. 盐酸HCI","C. H2SO4","D. 氢氧化钾KOH"],"answer":"A","explanation":"电解加工常用三种电解液：NaCl（加工效率高）、NaNO3（精度高）、NaClO3（综合性能好）。记忆：电解液\\"三种\\"。"},{"id":175,"type":"single","category":"电解加工","difficulty":3,"question":"电化学反应阳极表面金属离子来不及扩散造成堆积，引起了电位值增大，这是(        )。","options":["A. 浓差极化","B. 电化学极化","C. 电阻极化","D. 活化极化"],"answer":"A","explanation":"浓差极化是由于反应产物在电极表面堆积、浓度变化引起的极化现象。记忆：浓差极化\\"浓度变化\\"。"},{"id":176,"type":"single","category":"电解加工","difficulty":3,"question":"由于电化学反应速度缓慢会造成电极表面电荷积累、电位值增大，这是(        )。","options":["A. 浓差极化","B. 电化学极化","C. 电阻极化","D. 钝化极化"],"answer":"B","explanation":"电化学极化（活化极化）是由于电化学反应速度缓慢造成的极化现象。记忆：电化学极化\\"反应慢\\"。"},{"id":177,"type":"single","category":"电解加工","difficulty":3,"question":"电化学反应阳极表面生成一层钝化性氧化物膜或覆盖层，使电流通过困难，造成电位升高，这是(        )","options":["A. 浓差极化","B. 电化学极化","C. 钝化极化","D. 活化极化"],"answer":"C","explanation":"钝化极化是由于电极表面生成钝化膜，阻碍电流通过而产生的极化现象。记忆：钝化极化\\"有钝化膜\\"。"},{"id":178,"type":"single","category":"电解加工","difficulty":2,"question":"不完全钝化区可用于以下(        )。","options":["A. 电解加工","B. 电解抛光","C. 电刷镀","D. 电铸"],"answer":"B","explanation":"不完全钝化区阳极表面波谷溶解慢、尖角溶解快，可用于电解抛光。记忆：不完全钝化\\"可抛光\\"。"},{"id":179,"type":"single","category":"电解加工","difficulty":2,"question":"电解加工的表面粗糙度跟(        )有关。","options":["A. 工件成分组织","B. 电解液的流速","C. 电解液的温度","D. 以上都是"],"answer":"D","explanation":"电解加工表面粗糙度受工件材料、电解液流速、温度等多种因素影响。记忆：粗糙度\\"多因素\\"。"},{"id":180,"type":"single","category":"电解加工","difficulty":2,"question":"以下电解液体系，(        )加工速度最大，加工精度最差。","options":["A. NaCl","B. NaN03","C. NaClO3","D. NaCl+NaN03"],"answer":"A","explanation":"NaCl电解液导电率高，加工速度快，但杂散腐蚀严重，精度最差。记忆：NaCl\\"快但不精\\"。"},{"id":181,"type":"single","category":"电解加工","difficulty":2,"question":"以下电解液体系，(        )加工速度最慢，加工精度最高。","options":["A. NaCl","B. NaN03","C. NaClO3","D. NaCl+NaN03"],"answer":"B","explanation":"NaNO3电解液有非线性特性，加工精度最高，但加工速度较慢。记忆：NaNO3\\"精但慢\\"。"},{"id":182,"type":"single","category":"电解加工","difficulty":2,"question":"衡量电解液加工精度高低的指标是(        )。","options":["A. 杂散腐蚀","B. 电流密度","C. 电流效率","D. 加工速度非线性"],"answer":"A","explanation":"杂散腐蚀越小，电解液的加工精度越高。这是衡量精度的核心指标。记忆：精度看\\"杂散腐蚀\\"。"},{"id":183,"type":"single","category":"电解加工","difficulty":2,"question":"目前电解加工电源主要采用(        )。","options":["A. 直流发电机整流电源","B. 硅整流电源","C. 晶闸管整流电源","D. 晶体管整流电源"],"answer":"C","explanation":"目前电解加工主要采用晶闸管整流电源，效率高、控制方便。记忆：电解加工用\\"晶闸管\\"。"},{"id":184,"type":"single","category":"超声加工","difficulty":2,"question":"复杂工件的内腔部位毛刺可以采用(        )方式去除。","options":["A. 刀具切除","B. 电解加工","C. 超声加工","D. 激光加工"],"answer":"C","explanation":"超声加工可以加工复杂内腔，适合去除内腔毛刺。其他方法难以加工复杂内腔。记忆：超声加工\\"内腔毛刺\\"。"},{"id":185,"type":"single","category":"电解加工","difficulty":2,"question":"下列(        )加工方式要求镀层与基体不要结合牢固。","options":["A. 电镀","B. 电铸","C. 电刷镀","D. 复合镀"],"answer":"B","explanation":"电铸是制造零件，镀层最终要从基体上分离，所以不要求结合牢固。记忆：电铸\\"镀层要分离\\"。"},{"id":186,"type":"single","category":"电解加工","difficulty":2,"question":"纸币、证券模具可以采用(        )方式加工。","options":["A. 电火花","B. 电铸","C. 电解加工","D. 超声加工"],"answer":"B","explanation":"电铸可以精确复制微细纹理，适合制作纸币、证券模具。记忆：电铸\\"复制精细纹理\\"。"},{"id":187,"type":"single","category":"电解加工","difficulty":2,"question":"电解加工是利用金属在电解液中(        )作用进行加工的。","options":["A. 阳极溶解","B. 阴极沉积","C. 阳极覆盖","D. 阳极解析"],"answer":"A","explanation":"电解加工是利用阳极溶解原理，工件接正极，工具接负极。记忆：电解加工\\"阳极溶解\\"。"},{"id":188,"type":"single","category":"电解加工","difficulty":2,"question":"电解抛光是利用金属在电解液中(        )作用进行加工的。","options":["A. 阳极溶解","B. 阴极沉积","C. 阳极覆盖","D. 阳极解析"],"answer":"A","explanation":"电解抛光也是利用阳极溶解原理，使表面微观凸起优先溶解。记忆：电解抛光\\"阳极溶解\\"。"},{"id":189,"type":"single","category":"电解加工","difficulty":2,"question":"电铸加工是利用金属在电解液中(        )作用进行加工的。","options":["A. 阳极溶解","B. 阴极沉积","C. 阳极覆盖","D. 阳极解析"],"answer":"B","explanation":"电铸是利用阴极沉积原理，金属离子在阴极（芯模）上沉积形成零件。记忆：电铸\\"阴极沉积\\"。"},{"id":190,"type":"single","category":"电解加工","difficulty":2,"question":"电刷镀是利用金属在电解液中(        )作用进行加工的。","options":["A. 阳极溶解","B. 阴极沉积","C. 阳极覆盖","D. 阳极解析"],"answer":"B","explanation":"电刷镀是利用阴极沉积原理，金属离子在工件表面沉积形成镀层。记忆：电刷镀\\"阴极沉积\\"。"},{"id":191,"type":"single","category":"电解加工","difficulty":2,"question":"以下(        )的加工精度是最高的。","options":["A. 电火花","B. 电铸","C. 电刷镀","D. 电解加工"],"answer":"B","explanation":"电铸可以达到很高的精度，能够复制微米级的细节。精度最高。记忆：电铸\\"精度最高\\"。"},{"id":192,"type":"single","category":"超声加工","difficulty":2,"question":"以下最适合超声加工的材料是(        )。","options":["A. 石墨","B. 铝","C. 硬质合金","D. 大理石"],"answer":"D","explanation":"超声加工特别适合不导电的硬脆材料，大理石是典型的硬脆非金属材料。记忆：超声加工\\"硬脆非金属\\"。"},{"id":193,"type":"single","category":"超声加工","difficulty":2,"question":"对于不导电的非金属材料采用的加工方法是(        )。","options":["A. 电解加工","B. 电火花加工","C. 超声加工","D. 都可以"],"answer":"C","explanation":"电解和电火花需要导电材料，超声加工可以加工不导电的非金属材料。记忆：超声加工\\"不需导电\\"。"},{"id":194,"type":"single","category":"超声加工","difficulty":2,"question":"下列材料最适合超声加工的是(        )。","options":["A. 合金钢","B. 低碳钢","C. 陶瓷","D. 紫铜"],"answer":"C","explanation":"陶瓷是典型的硬脆非金属材料，最适合超声加工。金属材料一般不用超声加工。记忆：超声加工\\"切陶瓷\\"。"},{"id":195,"type":"single","category":"超声加工","difficulty":2,"question":"下列材料中，(        )最适合超声加工。","options":["A. 铝合金","B. 玻璃","C. 高碳钢","D. 黄铜"],"answer":"B","explanation":"玻璃是不导电的硬脆材料，最适合超声加工。铝合金、高碳钢、黄铜都是金属。记忆：超声加工\\"切玻璃\\"。"},{"id":196,"type":"single","category":"超声加工","difficulty":2,"question":"以下(        )不是常见的超声换能器。","options":["A. 100%的镍金属","B. 铁氧化体","C. 压电晶片","D. 电致伸缩"],"answer":"D","explanation":"常见的超声换能器有压电晶片、磁致伸缩（镍金属、铁氧体）等，电致伸缩不是常见类型。记忆：换能器\\"压电和磁致伸缩\\"。"},{"id":197,"type":"single","category":"超声加工","difficulty":2,"question":"大中功率超声换能器应该选择(        )。","options":["A. 100%的镍金属","B. 铁氧化体","C. 压电晶片","D. 电致伸缩"],"answer":"A","explanation":"大中功率超声换能器应选择磁致伸缩材料（如镍金属），功率容量大。压电晶片适合小功率。记忆：大功率用\\"磁致伸缩\\"。"},{"id":198,"type":"single","category":"超声加工","difficulty":2,"question":"在超声波的声学部件各连接面之间加入(        )作为传递介质，可以消除超声波在空气中传播引起的衰减。","options":["A. 机油","B. 凡士林","C. 橡胶垫","D. A和B"],"answer":"D","explanation":"机油和凡士林都是常用的声耦合剂，可以消除空气间隙，减少超声波衰减。记忆：耦合剂\\"机油凡士林\\"。"},{"id":199,"type":"single","category":"超声加工","difficulty":2,"question":"变幅杆加工具头总长度应该选定(        )。","options":["A. 波长的整数倍","B. 半波长的整数倍","C. 振幅的整数倍","D. 半振幅的整数倍"],"answer":"B","explanation":"变幅杆长度应为半波长的整数倍，以形成驻波，实现振幅放大。记忆：变幅杆\\"半波长整数倍\\"。"},{"id":200,"type":"single","category":"超声加工","difficulty":2,"question":"以下(        )有加工的工具损耗问题。","options":["A. 超声加工","B. 电解加工","C. 电子束加工","D. 激光加工"],"answer":"A","explanation":"超声加工工具（变幅杆和工具头）会与磨料摩擦产生损耗。这是超声加工的缺点。记忆：超声加工\\"有工具损耗\\"。"},{"id":201,"type":"judge","category":"电解加工","difficulty":2,"question":"阴极沉积加工时，工件接正极，工具接负极。","options":[],"answer":false,"explanation":"错误。阴极沉积时工件接负极（阴极），工具接正极（阳极）。记忆：阴极沉积\\"工件为负\\"。"},{"id":202,"type":"judge","category":"电解加工","difficulty":2,"question":"电解加工时，若工具电极的原始形状与工件待加工表面原始形状不同，则工件上各个加工点距离工具电极表面的距离就不等，各点的电流密度也不同。","options":[],"answer":true,"explanation":"正确。距离不同导致电流密度不同，这是电解加工能够成形的基本原理。记忆：电解成形\\"距离决定电流\\"。"},{"id":203,"type":"judge","category":"电解加工","difficulty":3,"question":"电解加工没有宏观的切削力，加工表面层不可能出现微细裂纹。","options":[],"answer":true,"explanation":"正确。电解加工是溶解过程，无切削力，表面不会产生机械裂纹。记忆：电解加工\\"无裂纹\\"。"},{"id":204,"type":"judge","category":"电解加工","difficulty":3,"question":"电解加工时由于电流的通过，电极的平衡状态被打破，使得阳极电位向正方向增大(代数值增大)。","options":[],"answer":true,"explanation":"正确。这是极化现象的描述，电流通过时阳极电位向正方向偏移。记忆：极化\\"电位偏移\\"。"},{"id":205,"type":"judge","category":"电解加工","difficulty":2,"question":"电解磨削时主要靠砂轮磨削作用来去除金属，电化学作用是为了加速磨削过程。","options":[],"answer":false,"explanation":"错误。电解磨削主要靠电化学溶解去除金属，砂轮只起磨除钝化膜和整平作用。记忆：电解磨削\\"电化学为主\\"。"},{"id":206,"type":"judge","category":"电解加工","difficulty":3,"question":"温度提高或金属正离子活度增加，均使金属电极的平衡电位朝正向增大。","options":[],"answer":true,"explanation":"正确。根据能斯特方程，温度和离子活度的变化会影响平衡电位。记忆：能斯特方程\\"影响电位\\"。"},{"id":207,"type":"judge","category":"电解加工","difficulty":3,"question":"温度提高或非金属负离子活度增加，均使非属电极的平衡电位朝负向增大(代数值减小)。","options":[],"answer":true,"explanation":"正确。根据能斯特方程，这些因素会使非金属电极电位向负方向变化。记忆：能斯特方程\\"负向变化\\"。"},{"id":208,"type":"judge","category":"电解加工","difficulty":2,"question":"阳极金属钝化现象的存在，会使电解加工中阳极溶解速度下降甚至停顿，所以它是有害的现象，在生产中应尽量避免。","options":[],"answer":false,"explanation":"错误。钝化现象可用于电解抛光，是有益的；只有在需要快速溶解时才是有害的。记忆：钝化\\"双面性\\"。"},{"id":209,"type":"judge","category":"电解加工","difficulty":2,"question":"电解加工是利用金属在电解液中阴极溶解作用去除材料的，电镀是利用阳极沉积作用进行镀覆加工的。","options":[],"answer":false,"explanation":"错误。说反了。电解加工是阳极溶解，电镀是阴极沉积。记忆：电解\\"阳极\\"，电镀\\"阴极\\"。"},{"id":210,"type":"judge","category":"电解加工","difficulty":3,"question":"电化学反应时，金属的电极电位越正，越易失去电子变成正离子溶解到溶液中去。","options":[],"answer":false,"explanation":"错误。电极电位越正，越难失去电子，越不易溶解；电位越负越易溶解。记忆：电位越负\\"越易溶\\"。"},{"id":211,"type":"judge","category":"电解加工","difficulty":2,"question":"氯化钠电解液在使用中，氯化钠成分不会损耗，不必经常添加补充。","options":[],"answer":true,"explanation":"正确。NaCl在电解过程中不参与反应，理论上不会损耗。记忆：NaCl\\"不损耗\\"。"},{"id":212,"type":"judge","category":"电解加工","difficulty":2,"question":"法拉第电解定律认为电解加工时电极上溶解或析出物质的量与通过的电量成正比，它也适合于电镀。","options":[],"answer":true,"explanation":"正确。法拉第定律适用于所有电化学过程，包括电解加工和电镀。记忆：法拉第定律\\"通用\\"。"},{"id":213,"type":"judge","category":"电解加工","difficulty":2,"question":"电解加工时，阳极金属除溶解外，虽然还有其他副反应，但阳极溶解的实际金属质量与理论金属质量一样。","options":[],"answer":false,"explanation":"错误。副反应会消耗电量，使实际溶解量小于理论值，需要用电流效率修正。记忆：实际溶解\\"小于理论\\"。"},{"id":214,"type":"judge","category":"电解加工","difficulty":2,"question":"电解加工时，被加工件金属材料组织不均匀或金属材料与电解液成分的匹配不当，但阳极溶解的实际金属质量与理论金属质量还是一样的。","options":[],"answer":false,"explanation":"错误。材料组织不均匀和匹配不当都会影响电流效率，使实际溶解量与理论值不同。记忆：溶解量\\"受多因素影响\\"。"},{"id":215,"type":"judge","category":"电解加工","difficulty":2,"question":"电解加工时，电解液的浓度越高，则加工精度越低。","options":[],"answer":true,"explanation":"正确。浓度越高，导电率越高，杂散腐蚀越严重，加工精度越低。记忆：浓度高\\"精度低\\"。"},{"id":216,"type":"judge","category":"电解加工","difficulty":2,"question":"电解液的种类，对电解加工的成形精度没有影响。","options":[],"answer":false,"explanation":"错误。不同电解液的杂散腐蚀特性不同，对成形精度影响很大。记忆：电解液种类\\"影响精度\\"。"},{"id":217,"type":"judge","category":"电解加工","difficulty":2,"question":"对进行复杂型腔的表面进行电解加工时，电解液流畅不易均匀，在流速、流量不足的局部区域电解量将偏小，且该处容易形成短路。","options":[],"answer":true,"explanation":"正确。复杂型腔电解液流动不均匀是常见问题，会导致加工不均匀和短路。记忆：复杂型腔\\"流动不均\\"。"},{"id":218,"type":"judge","category":"电解加工","difficulty":2,"question":"精电解加工时选高浓度的电解液，粗电解加工时选低浓度的电解液。","options":[],"answer":false,"explanation":"错误。说反了。精加工选低浓度（减少杂散腐蚀），粗加工选高浓度（提高效率）。记忆：精加工\\"低浓度\\"。"},{"id":219,"type":"judge","category":"超声加工","difficulty":2,"question":"超声加工不受被加工材料特性的限制，加工中也不会使材料产生化学变化。","options":[],"answer":true,"explanation":"正确。超声加工靠磨料冲击去除材料，不受导电性等限制，且是纯机械作用，无化学变化。记忆：超声加工\\"纯机械\\"。"},{"id":220,"type":"judge","category":"超声加工","difficulty":2,"question":"超声加工不能用于弱刚性零件的加工。","options":[],"answer":false,"explanation":"错误。超声加工作用力小，可以加工弱刚性零件，这是它的优点之一。记忆：超声加工\\"可加工弱刚性件\\"。"},{"id":221,"type":"judge","category":"超声加工","difficulty":2,"question":"超声加工时变幅杆的作用是将振动的振幅放大，以便于加工。","options":[],"answer":true,"explanation":"正确。变幅杆利用截面变化将振幅放大，提高加工能力。记忆：变幅杆\\"放大振幅\\"。"},{"id":222,"type":"judge","category":"超声加工","difficulty":2,"question":"超声加工时变幅杆的截面越小，截面上能量密度越大，振动的振幅就越大。","options":[],"answer":true,"explanation":"正确。根据能量守恒，截面小处能量集中，振幅增大。记忆：截面小\\"振幅大\\"。"},{"id":223,"type":"judge","category":"电解加工","difficulty":3,"question":"标准电极电位越低的金属，越容易得到电子被还原。","options":[],"answer":false,"explanation":"错误。电位越低（越负），越容易失去电子被氧化，不是得到电子被还原。记忆：电位越负\\"越易氧化\\"。"},{"id":224,"type":"judge","category":"超声加工","difficulty":2,"question":"超声加工特别适合于不导电的硬脆材料的加工，也能加工导电的硬脆金属材料。","options":[],"answer":true,"explanation":"正确。超声加工可以加工各种硬脆材料，包括导电和不导电的。记忆：超声加工\\"不限导电性\\"。"},{"id":225,"type":"judge","category":"电解加工","difficulty":2,"question":"阳极钝化现象的存在，会使电解加工中阳极溶解速度下降甚至停顿，所以是有害现象，在生产中应尽量避免它。","options":[],"answer":false,"explanation":"错误。钝化现象可用于电解抛光等场合，不完全是坏事。记忆：钝化\\"有好有坏\\"。"},{"id":226,"type":"judge","category":"电解加工","difficulty":2,"question":"两电极间隙较小处的电流密度大，阳极溶解的速度快。","options":[],"answer":true,"explanation":"正确。间隙小，电阻小，电流密度大，溶解速度快，这是电解加工能够自动成形的原理。记忆：间隙小\\"溶解快\\"。"},{"id":227,"type":"judge","category":"电解加工","difficulty":3,"question":"Fe在Nacl电解液中只发生Fe的溶解和H2的析出。","options":[],"answer":true,"explanation":"正确。在NaCl电解液中，铁主要发生阳极溶解，阴极主要析出氢气。记忆：铁在NaCl中\\"溶解+析氢\\"。"},{"id":228,"type":"judge","category":"电解加工","difficulty":2,"question":"电解加工速度和电流密度成正比，电流密度越大越好。","options":[],"answer":false,"explanation":"错误。电流密度过大，电解液温升过高、产生火花、表面质量下降，不是越大越好。记忆：电流密度\\"有上限\\"。"},{"id":229,"type":"judge","category":"电解加工","difficulty":2,"question":"电解液的浓度越大，温度愈高，则其电导率也愈高，蚀除能力越强。","options":[],"answer":true,"explanation":"正确。浓度和温度升高都会提高电解液的导电率，增强蚀除能力。记忆：浓度温度高\\"导电率高\\"。"},{"id":230,"type":"judge","category":"电解加工","difficulty":2,"question":"电解加工用脉冲电源可以提高电解加工的精度和效率。","options":[],"answer":false,"explanation":"错误。电解加工主要用直流电源，脉冲电源主要用于电火花加工。记忆：电解用\\"直流\\"。"},{"id":231,"type":"judge","category":"电解加工","difficulty":2,"question":"电解抛光比机械抛光有更小的粗糙度值Ra，并且表面没有加工变质层。","options":[],"answer":true,"explanation":"正确。电解抛光表面质量好，粗糙度小，且无机械加工的变质层。记忆：电解抛光\\"质量好\\"。"},{"id":232,"type":"judge","category":"电解加工","difficulty":2,"question":"电解加工是利用金属在电解液中阴极溶解作用去除材料的。","options":[],"answer":false,"explanation":"错误。电解加工是阳极溶解，不是阴极溶解。记忆：电解\\"阳极溶解\\"。"},{"id":233,"type":"judge","category":"电解加工","difficulty":2,"question":"在电解抛光过程中，利用阳极的不完全钝化现象，使阳极表面波谷位置溶解速度下降或停止，而表面尖角部分继续溶解，从而达到抛光的作用。","options":[],"answer":true,"explanation":"正确。这是电解抛光的基本原理，利用钝化膜的选择性溶解实现表面整平。记忆：电解抛光\\"钝化膜作用\\"。"},{"id":234,"type":"judge","category":"超声加工","difficulty":2,"question":"超声波从液体或固体传入到空气时，反射率接近100%。","options":[],"answer":true,"explanation":"正确。声阻抗差异大时反射率高，液体/固体与空气的声阻抗差异很大。记忆：超声波\\"空气反射强\\"。"},{"id":235,"type":"judge","category":"超声加工","difficulty":2,"question":"阶梯形变幅杆振幅放大倍数最高，但受负载阻力时振幅衰减严重，且容易产生应力集中。","options":[],"answer":true,"explanation":"正确。阶梯形变幅杆放大倍数高，但存在应力集中和负载敏感的缺点。记忆：阶梯形\\"放大高但有缺点\\"。"},{"id":236,"type":"judge","category":"超声加工","difficulty":2,"question":"随着换能器温度的升高,磁致伸缩效应产生的相对伸长率降低。","options":[],"answer":true,"explanation":"正确。磁致伸缩材料的伸长率随温度升高而降低，需要冷却措施。记忆：磁致伸缩\\"怕热\\"。"},{"id":237,"type":"judge","category":"超声加工","difficulty":2,"question":"超声波加工的工具头没有损耗。","options":[],"answer":false,"explanation":"错误。超声加工工具头会与磨料颗粒摩擦产生损耗，这是超声加工的缺点之一。记忆：超声工具\\"有损耗\\"。"},{"id":238,"type":"judge","category":"超声加工","difficulty":2,"question":"超声加工表面非但不会产生烧伤和表面变质层、热应力，反而对提高工件的疲劳强度和抗应力腐蚀能力有益。","options":[],"answer":true,"explanation":"正确。超声加工是冷加工，无热损伤，且表面有压应力，有利于提高疲劳强度。记忆：超声加工\\"无热损伤\\"。"},{"id":239,"type":"judge","category":"超声加工","difficulty":2,"question":"悬浮磨粒越细、工件材料硬度越高、超声振幅越小，超声加工表面粗糙度Ra值越小。","options":[],"answer":true,"explanation":"正确。这些因素都会使加工痕迹更细小，表面粗糙度值更小。记忆：超声加工\\"多因素影响粗糙度\\"。"},{"id":240,"type":"judge","category":"超声加工","difficulty":2,"question":"煤油或润滑油代替水可使超声加工表面粗糙度Ra值减小。","options":[],"answer":true,"explanation":"正确。使用煤油或润滑油作为工作液，可以减小表面粗糙度值。记忆：工作液影响\\"粗糙度\\"。"},{"id":241,"question":"以下(        )没有加工的工具损耗问题。","options":["A. 电火花加工","B. 离子束加工","C. 超声加工","D. 线切割加工"],"type":"single","answer":"B","category":"激光电子束离子束","difficulty":2,"explanation":"离子束加工是利用离子撞击工件表面去除材料，不涉及工具与工件的直接接触，因此没有工具损耗问题。电火花加工有电极损耗，超声加工有工具头磨损，线切割有电极丝损耗。记忆口诀：\\"离子束无接触，无损耗\\"。"},{"id":242,"question":"三种激光的加工精度依次是(        )。","options":["A. Nd:YAG激光>准分子激光>CO2激光。","B. Nd:YAG激光>CO2激光>准分子激光。","C. 准分子激光>Nd:YAG激光>CO2激光。","D. 准分子激光>CO2激光>Nd:YAG激光。"],"type":"single","answer":"C","category":"激光电子束离子束","difficulty":2,"explanation":"三种激光加工精度排序：准分子激光>Nd:YAG激光>CO2激光。准分子激光波长短、聚焦性好，精度最高；Nd:YAG激光次之；CO2激光波长最长，精度最低。记忆口诀：\\"波长越短精度越高\\"。"},{"id":243,"question":"激光切割低碳钢时，属于(        )。","options":["A. 气化切割","B. 熔化切割","C. 控制断裂切割","D. 氧化熔化切割"],"type":"single","answer":"D","category":"激光电子束离子束","difficulty":2,"explanation":"激光切割低碳钢时，氧气作为辅助气体，与高温金属发生氧化反应放出热量，属于氧化熔化切割。低碳钢熔点较低，氧气助燃可提高切割效率。记忆口诀：\\"切钢用氧气=氧化熔化\\"。"},{"id":244,"question":"对于激光焊接描述不正确的是(        )。","options":["A. 适合于在玻璃制成的密封容器里焊接那些对人体产生副作用的材料","B. 激光加热范围小，热影响区小","C. 属于非接触焊接","D. 不适合于微型零件和远距离或一些难以接近的部位的焊接"],"type":"single","answer":"D","category":"激光电子束离子束","difficulty":2,"explanation":"激光焊接适合微型零件和远距离焊接，这是它的优势之一。激光可通过光纤传输，能焊接难以接近的部位。其他描述正确：可在密封容器中焊接、热影响区小、属于非接触焊接。记忆口诀：\\"激光焊灵活可达\\"。"},{"id":245,"question":"在同样的激光器和功率密度作用下，以下(        )的吸收率最小。","options":["A. Ti","B. Ni","C. Al","D. Fe"],"type":"single","answer":"C","category":"激光电子束离子束","difficulty":2,"explanation":"金属对激光的吸收率与材料性质有关。Al（铝）对激光的反射率高，吸收率最小；Ti（钛）、Ni（镍）、Fe（铁）的吸收率相对较高。记忆口诀：\\"铝最亮最反光\\"。"},{"id":246,"question":"激光切割铝合金时，属于(        )。","options":["A. 控制断裂切割","B. 熔化切割","C. 氧化熔化切割","D. 气化切割"],"type":"single","answer":"B","category":"激光电子束离子束","difficulty":2,"explanation":"激光切割铝合金时，铝合金导热性好、反射率高，一般采用熔化切割，辅以惰性气体（如氮气）吹除熔融金属。铝合金不适合氧化切割，因为铝与氧反应剧烈。记忆口诀：\\"铝合金用惰性气体=熔化切割\\"。"},{"id":247,"question":"产生激光的前提条件有(        )","options":["A. 激光工作物质","B. 粒子数反转","C. 光学谐振腔","D. 以上都是"],"type":"single","answer":"D","category":"激光电子束离子束","difficulty":2,"explanation":"产生激光的三个前提条件：激光工作物质（增益介质）、粒子数反转（激励源提供能量）、光学谐振腔（放大和选频）。三者缺一不可。记忆口诀：\\"物质反转加谐振\\"。"},{"id":248,"question":"对激光切割中惰性的辅助气体的作用描述不正确的是(        )。","options":["A. 将熔化和气化的材料从切口吹掉","B. 去除材料表面的等离子体，提高材料对激光束的吸收","C. 与高温金属熔液发生放热反应，增加能量输入","D. 惰性的辅助气体可以防止切口氧化"],"type":"single","answer":"C","category":"激光电子束离子束","difficulty":2,"explanation":"惰性辅助气体（如氮气、氩气）的作用是：吹除熔化材料、去除等离子体、防止切口氧化。但惰性气体不会与金属发生放热反应，那是活性气体（如氧气）的作用。记忆口诀：\\"惰性不反应，只吹气保护\\"。"},{"id":249,"question":"下列哪种加工方式可不在真空中进行(        )","options":["A. 电子束焊接","B. 激光打孔","C. 电子束曝光","D. 离子束加工"],"type":"single","answer":"B","category":"激光电子束离子束","difficulty":2,"explanation":"激光打孔可在大气中进行，不需要真空环境。电子束焊接、电子束曝光、离子束加工都需要在真空环境中进行，因为电子和离子在空气中会与气体分子碰撞而散射。记忆口诀：\\"激光接地气，电子束怕空气\\"。"},{"id":250,"question":"下列(        )的束斑直径最大.加工精度最低。","options":["A. 等离子体加工","B. 激光加工","C. 离子束加工","D. 电子束焊接"],"type":"single","answer":"A","category":"激光电子束离子束","difficulty":2,"explanation":"等离子体加工的束斑直径最大，加工精度最低。离子束加工精度最高，电子束次之，激光再次。记忆口诀：\\"等离子体粗放，离子束精细\\"。"},{"id":251,"question":"下列(        )不属于热加工范畴。","options":["A. 离子束加工","B. 激光切割","C. 电子束打孔","D. 等离子体焊接"],"type":"single","answer":"A","category":"激光电子束离子束","difficulty":2,"explanation":"离子束加工是靠离子的动能（机械能）撞击工件去除材料，属于冷加工，不属于热加工。激光切割、电子束打孔、等离子体焊接都是利用热能加工。记忆口诀：\\"离子束冷加工\\"。"},{"id":252,"question":"高功率密度的离子束加工主要用于(        )。","options":["A. 工件表面改性","B. 工件切割","C. 工件焊接","D. 工件打孔"],"type":"single","answer":"A","category":"激光电子束离子束","difficulty":2,"explanation":"高功率密度的离子束主要用于工件表面改性（离子注入），可改变材料表面的物理化学性能。切割、焊接、打孔一般用激光或电子束。记忆口诀：\\"离子束改性，激光切焊打\\"。"},{"id":253,"question":"对于激光焊接描述不正确的是(        )。","options":["A. 激光可以通过光导纤维、棱镜等光学方法弯曲传输、偏转聚焦","B. 焊接接头抗疲劳性能良好和抗拉强度高","C. 可以焊接用一般方法难以焊接的材料","D. 一台激光器只能用于焊接，而不能用于切割、合金化和热处理"],"type":"single","answer":"D","category":"激光电子束离子束","difficulty":2,"explanation":"激光器用途广泛，一台激光器可用于焊接、切割、合金化、热处理、打标等多种加工。其他描述正确：可通过光纤传输、焊接接头性能好、可焊接难焊材料。记忆口诀：\\"激光一机多用\\"。"},{"id":254,"question":"对激光切割中活性的辅助气体的作用描述不正确的是(        )。","options":["A. 与高温金属熔液发生放热反应，增加能量输入","B. 去除材料表面的等离子体，提高材料对激光束的吸收","C. 与高温金属熔液发生放热反应，减少能量输入","D. 将熔化和气化的材料从切口吹掉"],"type":"single","answer":"C","category":"激光电子束离子束","difficulty":2,"explanation":"活性辅助气体（如氧气）与高温金属发生放热反应，是增加能量输入，不是减少。其他描述正确：吹除熔化材料、去除等离子体。记忆口诀：\\"活性气体助燃增能\\"。"},{"id":255,"question":"原子处于内部能量最低的状态，称为原子处于(        )。","options":["A. 平衡态","B. 高能态","C. 激发态","D. 基态"],"type":"single","answer":"D","category":"激光电子束离子束","difficulty":2,"explanation":"原子处于内部能量最低的状态称为基态。高能态和激发态是能量较高的状态，平衡态是热力学概念。记忆口诀：\\"基态=基本状态=最低能量\\"。"},{"id":256,"question":"以下(        )不属于激光淬火的特性。","options":["A. 加热速度快","B. 工件热变形小","C. 冷却速度快","D. 需要淬火介质"],"type":"single","answer":"D","category":"激光电子束离子束","difficulty":2,"explanation":"激光淬火的特性：加热速度快、冷却速度快、工件热变形小、不需要淬火介质（靠工件自身热传导冷却）。需要淬火介质是传统淬火的特点。记忆口诀：\\"激光淬火快冷自冷\\"。"},{"id":257,"question":"激光切割反面出现黏渣，可能的原因是(        )。","options":["A. 以上都是","B. 功率密度偏低","C. 切割速度过快","D. 辅助气压偏小"],"type":"single","answer":"A","category":"激光电子束离子束","difficulty":2,"explanation":"激光切割反面出现黏渣，可能原因有：功率密度偏低（能量不足）、切割速度过快（来不及气化）、辅助气压偏小（吹不走熔渣）。以上因素都可能导致黏渣。记忆口诀：\\"黏渣=能量不够或气吹不走\\"。"},{"id":258,"question":"对CO2激光器描述正确的是(        )。","options":["A. 脉冲或连续工作","B. 连续工作","C. 激光波长最短","D. 脉冲工作"],"type":"single","answer":"B","category":"激光电子束离子束","difficulty":2,"explanation":"CO2激光器是气体激光器，只能连续工作，不能脉冲工作。Nd:YAG激光器可以脉冲或连续工作。记忆口诀：\\"CO2连续输出\\"。"},{"id":259,"question":"激光切割反面出现倒V形，可能的原因是(        )。","options":["A. 切割速度过慢","B. 焦平面在下表面","C. 功率密度偏高","D. 以上都是"],"type":"single","answer":"D","category":"激光电子束离子束","difficulty":2,"explanation":"激光切割反面出现倒V形，可能原因：切割速度过慢（热量积累过多）、焦平面在下表面（焦点位置不当）、功率密度偏高（能量过大）。以上因素都可能导致。记忆口诀：\\"倒V=热过量或焦不对\\"。"},{"id":260,"question":"薄、小工件的焊接可以采用的焊接方式是(        )","options":["A. 深熔激光焊接","B. 氩弧焊","C. 热传导激光焊","D. 搅拌摩擦焊"],"type":"single","answer":"C","category":"激光电子束离子束","difficulty":2,"explanation":"薄、小工件的焊接适合采用热传导激光焊，热输入小、热影响区小、变形小。深熔激光焊适合厚板，氩弧焊热输入大，搅拌摩擦焊适合大件。记忆口诀：\\"薄件用热传导\\"。"},{"id":261,"question":"对电子束加工原理描述不正确的是(        )。","options":["A. 电子束斑直径较小","B. 靠热能加工","C. 有真空系统","D. 靠机械能加工"],"type":"single","answer":"D","category":"激光电子束离子束","difficulty":2,"explanation":"电子束加工是靠热能加工，不是机械能。高速电子撞击工件表面，动能转换成热能使材料熔化、气化去除。电子束在真空中进行，束斑直径小。记忆口诀：\\"电子束热加工\\"。"},{"id":262,"question":"下列(        )激光器对金属材料的吸收率最大。","options":["A. Nd:YAG","B. 准分子","C. 红宝石","D. CO2"],"type":"single","answer":"A","category":"激光电子束离子束","difficulty":2,"explanation":"Nd:YAG激光器波长较短（1.06μm），金属对其吸收率较大。CO2激光器波长较长（10.6μm），金属反射率高。准分子激光波长最短但主要用于非金属。记忆口诀：\\"波长越短金属吸收越好\\"。"},{"id":263,"question":"激光切割木材时，属于(        )。","options":["A. 熔化切割","B. 控制断裂切割","C. 氧化熔化切割","D. 气化切割"],"type":"single","answer":"D","category":"激光电子束离子束","difficulty":2,"explanation":"激光切割木材时，木材遇热直接气化（燃烧），属于气化切割。木材熔点低，热量集中时直接升华。记忆口诀：\\"木材一烧就化=气化切割\\"。"},{"id":264,"question":"(        )不是产生激光的前提条件。","options":["A. 谐振腔","B. 激光放大","C. 激励源","D. 激光工作介质"],"type":"single","answer":"B","category":"激光电子束离子束","difficulty":2,"explanation":"产生激光的前提条件是：谐振腔、激励源、激光工作介质。激光放大是激光器的功能，不是前提条件。记忆口诀：\\"三要素=谐振腔+激励源+介质\\"。"},{"id":265,"question":"高碳钢切割用的辅助气体是(        )。","options":["A. Ar","B. He","C. O2","D. N2"],"type":"single","answer":"C","category":"激光电子束离子束","difficulty":2,"explanation":"高碳钢切割用氧气作为辅助气体，利用氧化反应放热提高切割效率。氩气和氦气是惰性气体，氮气可用于不锈钢切割。记忆口诀：\\"切碳钢用氧气\\"。"},{"id":266,"question":"下列(        )不属于热加工范畴。","options":["A. 水射流切割","B. 电子束打孔","C. 等离子体焊接","D. 激光切割"],"type":"single","answer":"A","category":"激光电子束离子束","difficulty":2,"explanation":"水射流切割是利用高压水的动能切割材料，属于冷加工，不属于热加工。电子束打孔、等离子体焊接、激光切割都属于热加工。记忆口诀：\\"水射流冷切割\\"。"},{"id":267,"question":"激光不是自然光，是人造光，是通过(        )产生的。","options":["A. 受激辐射","B. 受激吸收","C. 自发辐射","D. 都可以"],"type":"single","answer":"A","category":"激光电子束离子束","difficulty":2,"explanation":"激光是通过受激辐射产生的。自发辐射产生普通光（如灯泡），受激辐射产生相干光（激光）。记忆口诀：\\"激光=受激辐射放大\\"。"},{"id":268,"question":"三种激光对金属热加工产生的热影响区和热变形区依次是(        )。","options":["A. CO2激光>Nd:YAG激光>准分子激光。","B. 准分子激光>Nd:YAG激光>CO2激光。","C. Nd:YAG激光>准分子激光>CO2激光。","D. 准分子激光>CO2激光>Nd:YAG激光。"],"type":"single","answer":"A","category":"激光电子束离子束","difficulty":2,"explanation":"三种激光的热影响区和热变形区排序：CO2激光>Nd:YAG激光>准分子激光。CO2激光波长长、热效应大，准分子激光波长短、热效应小。记忆口诀：\\"波长越长热影响越大\\"。"},{"id":269,"question":"下列(        )的束斑直径最小.加工精度最高。","options":["A. 等离子体加工","B. 电子束焊接","C. 激光加工","D. 离子束加工"],"type":"single","answer":"D","category":"激光电子束离子束","difficulty":2,"explanation":"离子束加工的束斑直径最小，加工精度最高。离子质量大、聚焦性好，可达纳米级精度。电子束、激光、等离子体的精度依次降低。记忆口诀：\\"离子束最精细\\"。"},{"id":270,"question":"对激光切割中辅助气体的作用描述不正确的是(        )。","options":["A. 将熔化和气化的材料从切口吹掉","B. 冷却切割邻近区域，以减小热影响区的尺寸","C. 能使从切缝溅射出的材料污染聚焦透镜","D. 去除材料表面的等离子体，提高材料对激光束的吸收"],"type":"single","answer":"C","category":"激光电子束离子束","difficulty":2,"explanation":"辅助气体的作用是：吹除熔化材料、冷却切割区、去除等离子体。辅助气体应保护聚焦透镜不被污染，而不是使材料污染透镜。记忆口诀：\\"气体保护透镜\\"。"},{"id":271,"question":"对激光切割过程描述不正确的是(        )。","options":["A. 没有刀具磨损","B. 受被加工材料限制","C. 属于热加工过程","D. 属于冷加工过程"],"type":"single","answer":"D","category":"激光电子束离子束","difficulty":2,"explanation":"激光切割属于热加工过程，利用激光的热能使材料熔化、气化。激光切割没有刀具磨损、不受材料硬度限制，但不是冷加工。记忆口诀：\\"激光热切割\\"。"},{"id":272,"question":"以下(        )不是激光加工的前提条件。","options":["A. 辅助气体","B. 激光谐振腔","C. 增益介质","D. 外界激励源"],"type":"single","answer":"A","category":"激光电子束离子束","difficulty":2,"explanation":"激光加工的前提条件是：激光谐振腔、增益介质、外界激励源。辅助气体是激光切割的工艺条件，不是激光产生的前提。记忆口诀：\\"三要素不含辅助气体\\"。"},{"id":273,"question":"金属表面对激光吸收率的大小依次是(        )。","options":["A. 准分子激光>CO2激光>Nd:YAG激光。","B. Nd:YAG激光>准分子激光>CO2激光。","C. 准分子激光>Nd:YAG激光>CO2激光。","D. Nd:YAG激光>CO2激光>准分子激光。"],"type":"single","answer":"C","category":"激光电子束离子束","difficulty":2,"explanation":"金属对激光吸收率排序：准分子激光>Nd:YAG激光>CO2激光。准分子激光波长短、光子能量大，吸收率最高。记忆口诀：\\"波长越短吸收率越高\\"。"},{"id":274,"question":"在同样的激光器和功率密度作用下，以下(        )的吸收率最小。","options":["A. Ni","B. Ti","C. Cu","D. Fe"],"type":"single","answer":"C","category":"激光电子束离子束","difficulty":2,"explanation":"Cu（铜）对激光的吸收率最小，反射率高。Ti（钛）、Ni（镍）、Fe（铁）的吸收率相对较高。记忆口诀：\\"铜最亮最反光\\"。"},{"id":275,"question":"激光切割玻璃时，属于(        )。","options":["A. 氧化熔化切割","B. 控制断裂切割","C. 熔化切割","D. 气化切割"],"type":"single","answer":"B","category":"激光电子束离子束","difficulty":2,"explanation":"激光切割玻璃时，玻璃是脆性材料，采用控制断裂切割，利用热应力使玻璃沿预定方向断裂。记忆口诀：\\"玻璃脆断=控制断裂切割\\"。"},{"id":276,"question":"以下(        )切割方式最适合切割木材。","options":["A. 控制断裂切割","B. 熔化切割","C. 气化切割","D. 氧化熔化切割"],"type":"single","answer":"C","category":"激光电子束离子束","difficulty":2,"explanation":"木材适合用气化切割，因为木材遇热直接燃烧气化，不会熔化。记忆口诀：\\"木材一烧就走=气化切割\\"。"},{"id":277,"question":"以下(        )不属于激光淬火的特性。","options":["A. 不需要淬火介质","B. 冷却速度快","C. 工件热变形大","D. 加热速度快"],"type":"single","answer":"C","category":"激光电子束离子束","difficulty":2,"explanation":"激光淬火的特性：加热速度快、冷却速度快、工件热变形小、不需要淬火介质。工件热变形大不是激光淬火的特性，相反变形小是其优点。记忆口诀：\\"激光淬火快且变形小\\"。"},{"id":278,"question":"(        )不是激光的特性。","options":["A. 透射性","B. 高亮度","C. 单色性","D. 方向性"],"type":"single","answer":"A","category":"激光电子束离子束","difficulty":2,"explanation":"激光的特性是：高亮度、单色性、方向性、相干性。透射性不是激光特有的性质，普通光也可以透射。记忆口诀：\\"激光四特性不含透射性\\"。"},{"id":279,"question":"对激光入射到被加工材料表面的能量，描述不正确的是(        )。","options":["A. 一部分能量被反射","B. 一部分能量透射损失","C. 全部被加工材料吸收","D. 一部分能量被加工材料吸收"],"type":"single","answer":"C","category":"激光电子束离子束","difficulty":2,"explanation":"激光入射到材料表面，一部分能量被反射，一部分透射损失，只有一部分被材料吸收用于加工。不是全部被吸收。记忆口诀：\\"激光能量=反射+透射+吸收\\"。"},{"id":280,"question":"对离子束加工原理描述不正确的是(        )。","options":["A. 靠热能实现加工","B. 有真空系统","C. 离子质量比电子大","D. 靠离子撞击实现加工"],"type":"single","answer":"A","category":"激光电子束离子束","difficulty":2,"explanation":"离子束加工是靠离子的动能（机械能）撞击工件去除材料，不是靠热能。离子质量大，撞击时动能转换为材料的去除能量。记忆口诀：\\"离子束动能撞击\\"。"},{"id":281,"question":"材料对激光的吸收，描述不正确的是(        )。","options":["A. 都无关","B. 与被加工材料性质、表面状况、温度有关","C. 与激光偏振特性有关","D. 与激光波长有关"],"type":"single","answer":"A","category":"激光电子束离子束","difficulty":2,"explanation":"材料对激光的吸收与激光波长、材料性质、表面状况、温度、偏振特性等都有关，不是都无关。记忆口诀：\\"吸收率受多因素影响\\"。"},{"id":282,"question":"对CO2激光器、Nd:YAG激光器、准分子激光器描述正确的是(        )。","options":["A. 准分子激光器波长最短","B. CO2激光器光斑直径最小","C. 都不对","D. Nd:YAG激光器输出功率最大"],"type":"single","answer":"A","category":"激光电子束离子束","difficulty":2,"explanation":"准分子激光器波长最短（紫外波段），CO2激光器波长最长（远红外），Nd:YAG居中。准分子激光精度最高但功率不一定最大。记忆口诀：\\"准分子波长最短\\"。"},{"id":283,"question":"光放大的本质是(        )。","options":["A. 受激辐射","B. 受激吸收","C. 自发辐射","D. 都可以"],"type":"single","answer":"A","category":"激光电子束离子束","difficulty":2,"explanation":"光放大的本质是受激辐射。受激辐射使光子数量增加，实现光放大。自发辐射产生普通光，受激吸收减少光子。记忆口诀：\\"放大=受激辐射\\"。"},{"id":284,"question":"薄、小工件的焊接可以采用的焊接方式是(        )","options":["A. 气焊","B. 深熔激光焊接","C. 氩弧焊","D. 超声波焊接"],"type":"single","answer":"D","category":"激光电子束离子束","difficulty":2,"explanation":"薄、小工件适合超声波焊接，热输入小、变形小。深熔激光焊和氩弧焊热输入大，气焊不适合精密焊接。记忆口诀：\\"薄件用超声波\\"。"},{"id":285,"question":"离子束加工利用离子注入技术加工的是(        )。","options":["A. 离子束刻蚀","B. 离子注入","C. 离子镀","D. 溅射镀膜"],"type":"single","answer":"B","category":"激光电子束离子束","difficulty":2,"explanation":"离子注入是将离子注入工件表面，改变材料表面性能。离子束刻蚀是去除材料，离子镀和溅射镀膜是镀覆。记忆口诀：\\"注入=改变性能\\"。"},{"id":286,"question":"激光能进行多光束同时加工。(        )","options":["A. 对","B. 错"],"type":"judge","answer":true,"category":"激光电子束离子束","difficulty":2,"explanation":"正确。激光可以通过分光镜分成多束，实现多光束同时加工，提高效率。记忆：激光\\"可分光多束\\"。"},{"id":287,"question":"电子束加工是靠电子加工撞击工件表面转换成热能去除材料。(        )","options":["A. 对","B. 错"],"type":"judge","answer":true,"category":"激光电子束离子束","difficulty":2,"explanation":"正确。电子束加工是高速电子撞击工件表面，动能转换成热能，使材料熔化、气化去除。记忆：电子束\\"动能转热能\\"。"},{"id":288,"question":"激光会受电场和磁场干扰。(        )","options":["A. 对","B. 错"],"type":"judge","answer":false,"category":"激光电子束离子束","difficulty":2,"explanation":"错误。激光是光，不受电场和磁场干扰。这是激光加工的优点之一，而电子束会受磁场影响。记忆：激光\\"不受电磁干扰\\"。"},{"id":289,"question":"激光切割加工的热影响区非常小，工件变形小，几乎没有氧化层。(        )","options":["A. 对","B. 错"],"type":"judge","answer":true,"category":"激光电子束离子束","difficulty":2,"explanation":"正确。激光切割热影响区小、变形小、切缝窄、氧化层薄，这是激光切割的优势。记忆：激光切割\\"热影响小\\"。"},{"id":290,"question":"固体激光器只能加工金属材料，气体激光器则只能切割非金属材料。(        )","options":["A. 对","B. 错"],"type":"judge","answer":false,"category":"激光电子束离子束","difficulty":2,"explanation":"错误。固体激光器（如Nd:YAG）和气体激光器（如CO2）都可以加工金属和非金属，只是适用范围不同。记忆：激光器\\"都可加工金属非金属\\"。"},{"id":291,"question":"激光脉冲波形对激光焊接无作用。(        )","options":["A. 对","B. 错"],"type":"judge","answer":false,"category":"激光电子束离子束","difficulty":2,"explanation":"错误。激光脉冲波形对焊接质量有重要影响，不同波形（如尖峰波、方波）适用于不同材料的焊接。记忆：脉冲波形\\"影响焊接质量\\"。"},{"id":292,"question":"等离子体加工也属于高能束的热加工。(        )","options":["A. 对","B. 错"],"type":"judge","answer":true,"category":"激光电子束离子束","difficulty":2,"explanation":"正确。等离子体加工利用高温等离子体的热能去除材料，属于高能束热加工。记忆：等离子体\\"热加工\\"。"},{"id":293,"question":"固体激光器打标时的功率和频率都是通过软件调节的。(        )","options":["A. 对","B. 错"],"type":"judge","answer":false,"category":"激光电子束离子束","difficulty":2,"explanation":"错误。固体激光器的功率和频率既可通过硬件调节，也可通过软件调节，现代激光器多采用软件控制。记忆：激光器\\"软硬件都可调\\"。"},{"id":294,"question":"激光焊接薄材料时,宜采用正离焦。(        )","options":["A. 对","B. 错"],"type":"judge","answer":true,"category":"激光电子束离子束","difficulty":2,"explanation":"正确。焊接薄材料时采用正离焦（焦点在工件上方），可使能量分布更均匀，避免焊穿。记忆：薄件焊接\\"正离焦\\"。"},{"id":295,"question":"电子束不仅可加工各种直的型孔面，也可加工弯孔、曲面和异形孔。(        )","options":["A. 对","B. 错"],"type":"judge","answer":true,"category":"激光电子束离子束","difficulty":2,"explanation":"正确。电子束可通过偏转磁场控制方向，能加工各种形状的孔和曲面，包括弯孔和异形孔。记忆：电子束\\"可加工弯孔\\"。"},{"id":296,"question":"离子束加工(如溅射.镀膜)是利用离子束的热效应来实现加工的。(        )","options":["A. 对","B. 错"],"type":"judge","answer":false,"category":"激光电子束离子束","difficulty":2,"explanation":"错误。离子束加工（如溅射、镀膜）是利用离子的动能（机械能）实现的，不是热效应。记忆：离子束\\"动能加工\\"。"},{"id":297,"question":"激光切割无需考虑材料的硬度。(        )","options":["A. 对","B. 错"],"type":"judge","answer":true,"category":"激光电子束离子束","difficulty":2,"explanation":"正确。激光切割是非接触加工，不受材料硬度影响，可切割各种硬度的材料。记忆：激光切割\\"不看硬度\\"。"},{"id":298,"question":"激光焊接速度提高会使熔深变浅，但速度过低又会导致工件焊穿。(        )","options":["A. 对","B. 错"],"type":"judge","answer":true,"category":"激光电子束离子束","difficulty":2,"explanation":"正确。焊接速度提高，能量输入减少，熔深变浅；速度过低，能量积累过多，会焊穿工件。记忆：焊接速度\\"适中最好\\"。"},{"id":299,"question":"激光切割加工的切缝细小，可以实现几乎任意轮廓线的切割。(        )","options":["A. 对","B. 错"],"type":"judge","answer":true,"category":"激光电子束离子束","difficulty":2,"explanation":"正确。激光切割切缝窄（0.1-0.3mm），可通过数控实现任意轮廓切割。记忆：激光切割\\"切缝窄轮廓自由\\"。"},{"id":300,"question":"离子束加工和电子束加工类似，都是使粒子加速撞击工件表面产生热量去除材料。(        )","options":["A. 对","B. 错"],"type":"judge","answer":false,"category":"激光电子束离子束","difficulty":2,"explanation":"错误。离子束加工是利用离子的动能撞击工件，电子束是利用电子的动能转换为热能，两者机理不同。记忆：离子束\\"动能\\"，电子束\\"热能\\"。"},{"id":301,"question":"由于离子的质量远大于电子，故离子束的加工效率高于电子束，但表面粗糙度差。(        )","options":["A. 对","B. 错"],"type":"judge","answer":false,"category":"激光电子束离子束","difficulty":2,"explanation":"错误。离子质量大，加工精度高，表面粗糙度反而更好（更小），不是更差。记忆：离子束\\"精度高粗糙度小\\"。"},{"id":302,"question":"CO2激光器可以切割非金属材料。(        )","options":["A. 对","B. 错"],"type":"judge","answer":true,"category":"激光电子束离子束","difficulty":2,"explanation":"正确。CO2激光器波长10.6μm，可被非金属材料（如木材、塑料、玻璃）吸收，适合切割非金属。记忆：CO2激光\\"切非金属\\"。"},{"id":303,"question":"激光加工和离子束加工相同，都要求有抽真空装置。(        )","options":["A. 对","B. 错"],"type":"judge","answer":false,"category":"激光电子束离子束","difficulty":2,"explanation":"错误。激光加工不需要真空，可在大气中进行；离子束加工需要真空环境。记忆：激光\\"不需真空\\"，离子束\\"需真空\\"。"},{"id":304,"question":"CO2激光器可以切割金属材料。(        )","options":["A. 对","B. 错"],"type":"judge","answer":true,"category":"激光电子束离子束","difficulty":2,"explanation":"正确。CO2激光器可以切割金属，但金属对其反射率高，通常需要较高功率或配合氧气辅助。记忆：CO2激光\\"可切金属\\"。"},{"id":305,"question":"激光焊接时当要求熔池较大时,宜采用负离焦。(        )","options":["A. 对","B. 错"],"type":"judge","answer":true,"category":"激光电子束离子束","difficulty":2,"explanation":"正确。焊接要求大熔池时采用负离焦（焦点在工件下方），可使能量更集中于工件内部。记忆：大熔池\\"负离焦\\"。"},{"id":306,"question":"激光打孔不需要抽真空,可在大气中进行打孔。(        )","options":["A. 对","B. 错"],"type":"judge","answer":true,"category":"激光电子束离子束","difficulty":2,"explanation":"正确。激光打孔可在大气中进行，不需要真空，这是激光加工的优点之一。记忆：激光打孔\\"不需真空\\"。"},{"id":307,"question":"激光合金化处理时，为防止氧化及元素烧损，必须在真空条件下进行。(        )","options":["A. 对","B. 错"],"type":"judge","answer":false,"category":"激光电子束离子束","difficulty":2,"explanation":"错误。激光合金化处理可在保护气氛（如氮气、氩气）中进行，不一定要真空。记忆：激光合金化\\"不需真空\\"。"},{"id":308,"question":"激光焊接通入保护气体是为增加物体对激光的吸收。(        )","options":["A. 对","B. 错"],"type":"judge","answer":false,"category":"激光电子束离子束","difficulty":2,"explanation":"错误。激光焊接通入保护气体主要是防止焊接区氧化，不是为增加对激光的吸收。记忆：保护气体\\"防氧化\\"。"},{"id":309,"question":"不可以改变激光的方向，只能直射。(        )","options":["A. 对","B. 错"],"type":"judge","answer":false,"category":"激光电子束离子束","difficulty":2,"explanation":"错误。激光可通过反射镜、光纤等改变方向，实现灵活传输和加工。记忆：激光\\"方向可变\\"。"},{"id":310,"question":"电子束在真空中才具备较长的自由行程，实现电子束高能量密度进行加工，但离子束加工中的离子因为质量大，动能大，因此加工时不需要真空环境。(        )","options":["A. 对","B. 错"],"type":"judge","answer":false,"category":"激光电子束离子束","difficulty":2,"explanation":"错误。离子束加工也需要真空环境，因为离子在空气中会与气体分子碰撞而散射，影响加工精度。记忆：离子束\\"也需真空\\"。"}]' WHERE id = 'precision-machining';